import { Body, Controller, Delete, Get, Param, Patch, Post, Req, UploadedFile, UploadedFiles, UseInterceptors } from '@nestjs/common'; import { FileInterceptor, FilesInterceptor } from '@nestjs/platform-express'; import { z } from 'zod'; import { StoreService } from './store.service'; import { mkdirSync, writeFileSync } from 'node:fs'; import { join } from 'node:path'; import { randomBytes } from 'node:crypto';
 @Controller() export class SocialController{constructor(private s:StoreService){} private ensureFriends(){this.s.db.exec("CREATE TABLE IF NOT EXISTS friend_lists(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,close_friends INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(user_id,name));CREATE TABLE IF NOT EXISTS friend_list_members(list_id INTEGER NOT NULL,user_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(list_id,user_id));CREATE TABLE IF NOT EXISTS contact_imports(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,contact TEXT NOT NULL,matched_user_id INTEGER,created_at TEXT NOT NULL,UNIQUE(user_id,contact));CREATE TABLE IF NOT EXISTS birthday_reminders(user_id INTEGER NOT NULL,friend_id INTEGER NOT NULL,birth_year INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,friend_id,birth_year));CREATE TABLE IF NOT EXISTS privacy_exceptions(owner_id INTEGER NOT NULL,viewer_id INTEGER NOT NULL,field TEXT NOT NULL,allowed INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(owner_id,viewer_id,field));")} private ensureProfile(){try{this.s.db.exec('ALTER TABLE users ADD COLUMN cover_url TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN status TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN emoji_status TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN verified INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN last_seen TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN first_name TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN last_name TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN nickname TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN city TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN country TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN birth_date TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN education TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN career TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN contacts TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN family_status TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN website TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN interests TEXT')}catch{}try{this.s.db.exec('ALTER TABLE users ADD COLUMN signature TEXT')}catch{}try{this.s.db.exec("ALTER TABLE users ADD COLUMN privacy_json TEXT NOT NULL DEFAULT '{}'")}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN pinned INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN idempotency_key TEXT')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN updated_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN deleted_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN archived INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN comments_enabled INTEGER NOT NULL DEFAULT 1')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN scheduled_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN is_ad INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN ad_label TEXT')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN attachment_json TEXT')}catch{}try{this.s.db.exec('ALTER TABLE posts ADD COLUMN wall_id INTEGER')}catch{}this.s.db.exec("CREATE UNIQUE INDEX IF NOT EXISTS posts_author_idempotency ON posts(author_id,idempotency_key) WHERE idempotency_key IS NOT NULL; CREATE TABLE IF NOT EXISTS profile_media(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,kind TEXT NOT NULL,url TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS profile_links(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT NOT NULL,url TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS post_hashtags(post_id INTEGER NOT NULL,tag TEXT NOT NULL,UNIQUE(post_id,tag)); CREATE TABLE IF NOT EXISTS post_mentions(post_id INTEGER NOT NULL,user_id INTEGER NOT NULL,username TEXT NOT NULL,UNIQUE(post_id,user_id)); CREATE TABLE IF NOT EXISTS post_links(post_id INTEGER NOT NULL,url TEXT NOT NULL,hostname TEXT NOT NULL,title TEXT NOT NULL,UNIQUE(post_id,url)); CREATE TABLE IF NOT EXISTS post_polls(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,question TEXT NOT NULL,multiple INTEGER NOT NULL DEFAULT 0,expires_at TEXT); CREATE TABLE IF NOT EXISTS poll_options(id INTEGER PRIMARY KEY AUTOINCREMENT,poll_id INTEGER NOT NULL,label TEXT NOT NULL,position INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS poll_votes(poll_id INTEGER NOT NULL,option_id INTEGER NOT NULL,user_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(poll_id,option_id,user_id)); CREATE TABLE IF NOT EXISTS user_blocks(blocker_id INTEGER NOT NULL,blocked_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(blocker_id,blocked_id)); CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,reporter_id INTEGER NOT NULL,target_type TEXT NOT NULL,target_id INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open'); CREATE TABLE IF NOT EXISTS drafts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,context TEXT NOT NULL,body TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_id,context)); CREATE TABLE IF NOT EXISTS post_revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,editor_id INTEGER NOT NULL,body TEXT NOT NULL,visibility TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS bookmarks(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,post_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,post_id))")}
 private indexPostMetadata(postId:number,body:string){this.ensureProfile();this.s.db.prepare('DELETE FROM post_hashtags WHERE post_id=?').run(postId);this.s.db.prepare('DELETE FROM post_mentions WHERE post_id=?').run(postId);this.s.db.prepare('DELETE FROM post_links WHERE post_id=?').run(postId);const tags=[...body.matchAll(/(^|\s)#([\p{L}\p{N}_-]{1,64})/gu)].map(x=>x[2].toLowerCase());const tagStmt=this.s.db.prepare('INSERT OR IGNORE INTO post_hashtags(post_id,tag) VALUES(?,?)');for(const tag of tags)tagStmt.run(postId,tag);const mentionStmt=this.s.db.prepare('INSERT OR IGNORE INTO post_mentions(post_id,user_id,username) VALUES(?,?,?)');for(const username of [...body.matchAll(/(^|\s)@([a-z0-9_]{3,24})/gi)].map(x=>x[2].toLowerCase())){const user=this.s.db.prepare('SELECT id,username FROM users WHERE username=? AND deleted_at IS NULL').get(username) as any;if(user)mentionStmt.run(postId,user.id,user.username)}const linkStmt=this.s.db.prepare('INSERT OR IGNORE INTO post_links(post_id,url,hostname,title) VALUES(?,?,?,?)');for(const raw of body.match(/https?:\/\/[^\s<]+/gi)||[]){try{const url=new URL(raw);if(url.protocol==='http:'||url.protocol==='https:')linkStmt.run(postId,url.href,url.hostname,url.hostname)}catch{}}}
 private savePoll(postId:number,poll:any){if(!poll)return;this.ensurePollOptions();const x=z.object({question:z.string().trim().min(2).max(300),options:z.array(z.string().trim().min(1).max(120)).min(2).max(10),multiple:z.boolean().default(false),anonymous:z.boolean().default(false),allowChange:z.boolean().default(false),expiresAt:z.string().datetime().nullable().optional()}).parse(poll);const q=this.s.db.prepare('INSERT INTO post_polls(post_id,question,multiple,anonymous,allow_change,expires_at) VALUES(?,?,?,?,?,?)').run(postId,x.question,x.multiple?1:0,x.anonymous?1:0,x.allowChange?1:0,x.expiresAt||null);const stmt=this.s.db.prepare('INSERT INTO poll_options(poll_id,label,position) VALUES(?,?,?)');x.options.forEach((label,position)=>stmt.run(Number(q.lastInsertRowid),label,position));}
 private notifyPostMentions(postId:number,body:string,authorId:number){this.ensureProfile();const mentioned=[...body.matchAll(/(^|\s)@([a-z0-9_]{3,24})/gi)].map(x=>x[2].toLowerCase());const seen=new Set<number>();for(const username of mentioned){const target=this.s.db.prepare('SELECT id FROM users WHERE username=? AND id<>? AND deleted_at IS NULL').get(username,authorId) as any;if(target&&!seen.has(target.id)){seen.add(target.id);this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(target.id,'mention',`Вас упомянули в публикации #${postId}`,this.s.now());}}}
 private notifyPostAuthor(postId:number,actorId:number,kind:string,text:string){this.ensureProfile();const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=?').get(postId) as any;if(post&&post.authorId!==actorId)this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(post.authorId,kind,text,this.s.now());}
 private ensurePostMedia(){this.s.db.exec('CREATE TABLE IF NOT EXISTS post_media(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,user_id INTEGER NOT NULL,kind TEXT NOT NULL,url TEXT NOT NULL,mime TEXT NOT NULL,created_at TEXT NOT NULL)')}
 private ensurePollOptions(){this.ensureProfile();try{this.s.db.exec('ALTER TABLE post_polls ADD COLUMN anonymous INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE post_polls ADD COLUMN allow_change INTEGER NOT NULL DEFAULT 0')}catch{}}
 private ensureStoryMedia(){this.ensureFeed();try{this.s.db.exec('ALTER TABLE stories ADD COLUMN media_url TEXT')}catch{}try{this.s.db.exec('ALTER TABLE stories ADD COLUMN media_kind TEXT')}catch{}try{this.s.db.exec('ALTER TABLE stories ADD COLUMN media_mime TEXT')}catch{}}
 private ensureProfileExtras(){this.ensureProfile();this.s.db.exec("CREATE TABLE IF NOT EXISTS profile_verification_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,UNIQUE(user_id,status)); CREATE TABLE IF NOT EXISTS gifts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,emoji TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1); CREATE TABLE IF NOT EXISTS user_gifts(id INTEGER PRIMARY KEY AUTOINCREMENT,gift_id INTEGER NOT NULL,sender_id INTEGER NOT NULL,recipient_id INTEGER NOT NULL,message TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL)");const count=this.s.db.prepare('SELECT COUNT(*) count FROM gifts').get() as any;if(!count.count)this.s.db.prepare("INSERT INTO gifts(name,emoji) VALUES('Цветок','🌷'),('Звезда','⭐'),('Сердце','💙')").run();}
 private ensurePostLocation(){this.ensureProfile();this.s.db.exec('CREATE TABLE IF NOT EXISTS post_locations(post_id INTEGER PRIMARY KEY,latitude REAL NOT NULL,longitude REAL NOT NULL,label TEXT NOT NULL DEFAULT \'\',created_at TEXT NOT NULL)')}
 private ensureMessages(){try{this.s.db.exec('ALTER TABLE messages ADD COLUMN silent INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN pinned INTEGER NOT NULL DEFAULT 0')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN attachments_json TEXT NOT NULL DEFAULT \'[]\'')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN reply_to INTEGER')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN edited_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN deleted_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN read_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN scheduled_at TEXT')}catch{}try{this.s.db.exec('ALTER TABLE messages ADD COLUMN client_key TEXT')}catch{}this.s.db.exec('CREATE UNIQUE INDEX IF NOT EXISTS messages_sender_client_key ON messages(sender_id,client_key) WHERE client_key IS NOT NULL;CREATE TABLE IF NOT EXISTS chat_preferences(user_id INTEGER NOT NULL,peer_id INTEGER NOT NULL,muted INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,pinned INTEGER NOT NULL DEFAULT 0,favorite INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,UNIQUE(user_id,peer_id));');try{this.s.db.exec('ALTER TABLE chat_preferences ADD COLUMN favorite INTEGER NOT NULL DEFAULT 0')}catch{}this.s.db.exec('CREATE TABLE IF NOT EXISTS message_reactions(message_id INTEGER NOT NULL,user_id INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT \'like\',UNIQUE(message_id,user_id));CREATE TABLE IF NOT EXISTS chat_folders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,name));CREATE TABLE IF NOT EXISTS chat_folder_peers(folder_id INTEGER NOT NULL,peer_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(folder_id,peer_id));CREATE TABLE IF NOT EXISTS chat_system_events(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,actor_id INTEGER NOT NULL,kind TEXT NOT NULL,text TEXT NOT NULL,created_at TEXT NOT NULL)')}
 private ensureDiscussion(){this.ensureEngagement();try{this.s.db.exec('ALTER TABLE comments ADD COLUMN pinned INTEGER NOT NULL DEFAULT 0')}catch{}this.s.db.exec('CREATE TABLE IF NOT EXISTS comment_subscriptions(post_id INTEGER NOT NULL,user_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(post_id,user_id)); CREATE TABLE IF NOT EXISTS comment_media(id INTEGER PRIMARY KEY AUTOINCREMENT,comment_id INTEGER NOT NULL,user_id INTEGER NOT NULL,kind TEXT NOT NULL,url TEXT NOT NULL,mime TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS moderation_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER NOT NULL,action TEXT NOT NULL,target_type TEXT NOT NULL,target_id INTEGER NOT NULL,created_at TEXT NOT NULL)')}
 @Get('health') health(){return {ok:true,service:'bluebird-api'}}
 private ensureFeed(){this.s.db.exec('CREATE TABLE IF NOT EXISTS hidden_posts(user_id INTEGER NOT NULL,post_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,post_id)); CREATE TABLE IF NOT EXISTS hidden_authors(user_id INTEGER NOT NULL,author_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,author_id)); CREATE TABLE IF NOT EXISTS feed_preferences(user_id INTEGER PRIMARY KEY,mode TEXT NOT NULL DEFAULT \'fresh\'); CREATE TABLE IF NOT EXISTS stories(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,body TEXT NOT NULL,audience TEXT NOT NULL DEFAULT \'public\',created_at TEXT NOT NULL,expires_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS story_views(story_id INTEGER NOT NULL,user_id INTEGER NOT NULL,viewed_at TEXT NOT NULL,UNIQUE(story_id,user_id))')}
 @Get('feed') feed(@Req() req:any){this.ensureFeed();this.ensureProfile();const v=this.s.auth(req);const cursor=Number(req.query?.cursor||0);const mode=String(req.query?.mode||'fresh');const source=String(req.query?.source||(['photo','video','text'].includes(mode)?mode:'all'));const limit=Math.min(Number(req.query?.limit||20),50);const following=mode==='following'&&v;const recommended=mode==='recommended';const where=following?"((p.visibility='public') OR (p.visibility='friends' AND EXISTS(SELECT 1 FROM friendships fp WHERE fp.status='accepted' AND ((fp.requester_id=? AND fp.addressee_id=p.author_id) OR (fp.addressee_id=? AND fp.requester_id=p.author_id))))) AND (p.author_id=? OR EXISTS(SELECT 1 FROM follows f WHERE f.follower_id=? AND f.following_id=p.author_id) OR EXISTS(SELECT 1 FROM friendships fr WHERE fr.status='accepted' AND ((fr.requester_id=? AND fr.addressee_id=p.author_id) OR (fr.addressee_id=? AND fr.requester_id=p.author_id))))":"p.visibility='public'";const params:any[]=following?[v,v,v,v,v,v]:[];let sql=`SELECT p.id FROM posts p WHERE ${where} AND p.deleted_at IS NULL AND p.archived=0 AND (p.scheduled_at IS NULL OR p.scheduled_at<=?) AND NOT EXISTS(SELECT 1 FROM hidden_posts h WHERE h.user_id=? AND h.post_id=p.id) AND NOT EXISTS(SELECT 1 FROM hidden_authors ha WHERE ha.user_id=? AND ha.author_id=p.author_id) AND NOT EXISTS(SELECT 1 FROM user_blocks b WHERE b.blocker_id=? AND b.blocked_id=p.author_id)`;params.push(this.s.now(),v||0,v||0,v||0);if(['photo','video','text'].includes(source)){this.ensurePostMedia();sql+=source==='text'?" AND NOT EXISTS(SELECT 1 FROM post_media pm WHERE pm.post_id=p.id)":` AND EXISTS(SELECT 1 FROM post_media pm WHERE pm.post_id=p.id AND pm.kind ${source==='photo'?"IN ('photo','gif')":"='video'"})`;}if(cursor){sql+=' AND p.id<?';params.push(cursor)}sql+=recommended?' ORDER BY (SELECT COUNT(*) FROM reactions r WHERE r.post_id=p.id)*3+(SELECT COUNT(*) FROM comments c WHERE c.post_id=p.id)*2 DESC,p.id DESC LIMIT ?':' ORDER BY p.id DESC LIMIT ?';params.push(limit+1);const rows=this.s.db.prepare(sql).all(...params) as any[];const page=rows.slice(0,limit);return {items:page.map(x=>this.s.post(x.id,v)).filter(Boolean),nextCursor:rows.length>limit?page[page.length-1]?.id:null,mode};}
 @Post('feed/preferences') feedPreferences(@Req() req:any,@Body() b:any){this.ensureFeed();const id=this.s.auth(req);if(!id)return {error:'Требуется вход',code:'UNAUTHORIZED'};const mode=z.enum(['fresh','following','recommended','text','photo','video']).parse(b.mode);this.s.db.prepare('INSERT INTO feed_preferences(user_id,mode) VALUES(?,?) ON CONFLICT(user_id) DO UPDATE SET mode=excluded.mode').run(id,mode);return {mode};}
 @Post('feed/hide/:id') hidePost(@Req() req:any,@Param('id') id:string){this.ensureFeed();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};this.s.db.prepare('INSERT OR IGNORE INTO hidden_posts(user_id,post_id,created_at) VALUES(?,?,?)').run(user,+id,this.s.now());return {hidden:true};}
 @Post('feed/hide-author/:authorId') hideAuthor(@Req() req:any,@Param('authorId') authorId:string){this.ensureFeed();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};this.s.db.prepare('INSERT OR IGNORE INTO hidden_authors(user_id,author_id,created_at) VALUES(?,?,?)').run(user,+authorId,this.s.now());return {hidden:true};}
 @Post('feed/not-interested/:authorId') notInterested(@Req() req:any,@Param('authorId') authorId:string){return this.hideAuthor(req,authorId);}
 @Get('stories') stories(@Req() req:any){this.ensureStoryMedia();const user=this.s.auth(req);const rows=this.s.db.prepare("SELECT s.id,s.body,s.media_url mediaUrl,s.media_kind mediaKind,s.media_mime mediaMime,s.audience,s.created_at createdAt,s.expires_at expiresAt,u.id userId,u.username,u.display_name displayName,(SELECT COUNT(*) FROM story_views v WHERE v.story_id=s.id) views,(SELECT 1 FROM story_views v WHERE v.story_id=s.id AND v.user_id=?) viewed FROM stories s JOIN users u ON u.id=s.user_id WHERE s.expires_at>? AND (s.audience='public' OR s.user_id=? OR EXISTS(SELECT 1 FROM friendships f WHERE f.status='accepted' AND ((f.requester_id=? AND f.addressee_id=s.user_id) OR (f.addressee_id=? AND f.requester_id=s.user_id)))) ORDER BY s.id DESC LIMIT 50").all(user,this.s.now(),user,user,user);return {items:rows};}
 @Post('stories') createStory(@Req() req:any,@Body() b:any){this.ensureFeed();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({body:z.string().trim().min(1).max(1000),audience:z.enum(['public','friends']).default('public')}).parse(b);const now=this.s.now();const expires=new Date(Date.now()+86400000).toISOString();const q=this.s.db.prepare('INSERT INTO stories(user_id,body,audience,created_at,expires_at) VALUES(?,?,?,?,?)').run(user,x.body,x.audience,now,expires);return {id:Number(q.lastInsertRowid),body:x.body,audience:x.audience,expiresAt:expires};}
 @Post('stories/:id/media') @UseInterceptors(FileInterceptor('file')) uploadStoryMedia(@Req() req:any,@Param('id') id:string,@UploadedFile() file:any){this.ensureStoryMedia();const user=this.s.auth(req);const story=this.s.db.prepare('SELECT user_id userId FROM stories WHERE id=? AND expires_at>?').get(+id,this.s.now()) as any;if(!user||!story||story.userId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};if(!file)return {error:'Файл обязателен',code:'NO_FILE'};const image=/^image\/(jpeg|png|webp|gif)$/.test(file.mimetype);const video=/^video\/(mp4|webm|quicktime)$/.test(file.mimetype);if((!image&&!video)||file.size>50*1024*1024)return {error:'Разрешены фото и видео до 50 МБ',code:'INVALID_FILE'};const kind=image?'photo':'video';const ext=file.mimetype.split('/')[1].replace('jpeg','jpg').replace('quicktime','mov');const filename=`story-${id}-${randomBytes(8).toString('hex')}.${ext}`;mkdirSync(join(process.cwd(),'uploads'),{recursive:true});writeFileSync(join(process.cwd(),'uploads',filename),file.buffer);const url=`/uploads/${filename}`;this.s.db.prepare('UPDATE stories SET media_url=?,media_kind=?,media_mime=? WHERE id=?').run(url,kind,file.mimetype,+id);return {url,kind};}
 @Post('stories/:id/view') viewStory(@Req() req:any,@Param('id') id:string){this.ensureFeed();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};this.s.db.prepare('INSERT OR IGNORE INTO story_views(story_id,user_id,viewed_at) VALUES(?,?,?)').run(+id,user,this.s.now());return {viewed:true};}
 @Delete('stories/:id') deleteStory(@Req() req:any,@Param('id') id:string){this.ensureFeed();const user=this.s.auth(req);const q=this.s.db.prepare('DELETE FROM stories WHERE id=? AND user_id=?').run(+id,user);return {deleted:q.changes>0};}
 @Get('stories/archive') storyArchive(@Req() req:any){this.ensureFeed();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};return {items:this.s.db.prepare('SELECT id,body,media_url mediaUrl,media_kind mediaKind,created_at createdAt,expires_at expiresAt FROM stories WHERE user_id=? AND expires_at<=? ORDER BY id DESC LIMIT 100').all(user,this.s.now())};}
 @Post('stories/:id/react') reactStory(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureFeed();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};this.s.db.exec('CREATE TABLE IF NOT EXISTS story_reactions(story_id INTEGER NOT NULL,user_id INTEGER NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(story_id,user_id))');const kind=z.string().trim().min(1).max(32).default('like').parse(b?.kind);const story=this.s.db.prepare('SELECT id FROM stories WHERE id=? AND expires_at>?').get(+id,this.s.now()) as any;if(!story)return {error:'История не найдена',code:'NOT_FOUND'};this.s.db.prepare('INSERT INTO story_reactions(story_id,user_id,kind,created_at) VALUES(?,?,?,?) ON CONFLICT(story_id,user_id) DO UPDATE SET kind=excluded.kind,created_at=excluded.created_at').run(+id,user,kind,this.s.now());return {reacted:true,kind};}
 @Get('feed/activity') feedActivity(@Req() req:any){this.ensureEngagement();const user=this.s.auth(req);if(!user)return {days:[],totals:{posts:0,reactions:0,comments:0}};const totals=this.s.db.prepare("SELECT (SELECT COUNT(*) FROM posts WHERE author_id=? AND created_at>=datetime('now','-7 days') AND deleted_at IS NULL) posts,(SELECT COUNT(*) FROM reactions r JOIN posts p ON p.id=r.post_id WHERE p.author_id=? AND r.created_at>=datetime('now','-7 days')) reactions,(SELECT COUNT(*) FROM comments c JOIN posts p ON p.id=c.post_id WHERE p.author_id=? AND c.created_at>=datetime('now','-7 days')) comments").get(user,user,user);const days=this.s.db.prepare("SELECT substr(created_at,1,10) day,COUNT(*) total FROM (SELECT created_at FROM posts WHERE author_id=? UNION ALL SELECT r.created_at FROM reactions r JOIN posts p ON p.id=r.post_id WHERE p.author_id=? UNION ALL SELECT c.created_at FROM comments c JOIN posts p ON p.id=c.post_id WHERE p.author_id=?) WHERE created_at>=datetime('now','-7 days') GROUP BY day ORDER BY day").all(user,user,user);return {days,totals};}
 @Get('feed/recommendations') feedRecommendations(@Req() req:any){this.ensureFeed();this.ensureProfile();this.groups();const user=this.s.auth(req);if(!user)return {authors:[],groups:[]};const authors=this.s.db.prepare("SELECT u.id,u.username,u.display_name displayName,u.avatar_url avatarUrl,COUNT(p.id) posts FROM users u LEFT JOIN posts p ON p.author_id=u.id AND p.deleted_at IS NULL WHERE u.id!=? AND u.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM follows f WHERE f.follower_id=? AND f.following_id=u.id) AND NOT EXISTS(SELECT 1 FROM user_blocks b WHERE b.blocker_id=? AND b.blocked_id=u.id) AND NOT EXISTS(SELECT 1 FROM reports r WHERE r.reporter_id=? AND r.target_type='user' AND r.target_id=u.id AND r.status='open') GROUP BY u.id ORDER BY posts DESC,u.created_at DESC LIMIT 6").all(user,user,user,user);const groups=this.s.db.prepare('SELECT id,name,slug,description FROM groups ORDER BY id DESC LIMIT 6').all();return {authors,groups};}
 @Post('posts/preview') async postPreview(@Req() req:any,@Body() b:any){const x=z.object({url:z.string().url().max(500)}).parse(b);const target=new URL(x.url);if(!['http:','https:'].includes(target.protocol))return {error:'Разрешены только http/https ссылки',code:'INVALID_URL'};const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),3500);try{const response=await fetch(target,{headers:{'user-agent':'BluebirdPreview/1.0','accept':'text/html'},signal:controller.signal});if(!response.ok)return {url:x.url,hostname:target.hostname,title:target.hostname,description:''};const html=(await response.text()).slice(0,300000);const readMeta=(property:string)=>{const match=html.match(new RegExp("<meta[^>]+(?:property|name)=[\\\"']"+property+"[\\\"][^>]+content=[\\\"']([^\\\"']*)[\\\"']","i"));return match?.[1]?.replace(/&amp;/g,'&').trim()||''};const title=readMeta('og:title')||target.hostname;return {url:x.url,hostname:target.hostname,title,description:readMeta('og:description'),image:readMeta('og:image')};}catch{return {url:x.url,hostname:target.hostname,title:target.hostname,description:''};}finally{clearTimeout(timer);}}
 @Post('posts') create(@Req() req:any,@Body() b:any){this.ensureProfile();const user=this.s.auth(req); if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'}; const x=z.object({body:z.string().min(1).max(5000),visibility:z.enum(['public','friends','private']).default('public'),wallUserId:z.number().int().positive().nullable().optional(),idempotencyKey:z.string().min(8).max(100).optional(),commentsEnabled:z.boolean().default(true),scheduledAt:z.string().datetime().nullable().optional(),poll:z.any().nullable().optional(),attachment:z.object({type:z.enum(['product','article','event']),title:z.string().trim().min(1).max(160),url:z.string().url().max(500)}).nullable().optional(),isAd:z.boolean().default(false),adLabel:z.string().trim().max(80).default('Реклама')}).parse(b);if(x.idempotencyKey){const old=this.s.db.prepare('SELECT id FROM posts WHERE author_id=? AND idempotency_key=?').get(user,x.idempotencyKey) as any;if(old)return {post:this.s.post(old.id,user),deduplicated:true};}const wall=x.wallUserId?this.s.db.prepare('SELECT id FROM users WHERE id=? AND deleted_at IS NULL').get(x.wallUserId) as any:null;if(x.wallUserId&&(!wall||(x.wallUserId!==user&&!this.s.db.prepare("SELECT 1 FROM friendships WHERE status='accepted' AND ((requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?))").get(user,x.wallUserId,x.wallUserId,user))))return {error:'Нет прав публиковать на этой стене',code:'FORBIDDEN'};const q=this.s.db.prepare('INSERT INTO posts(author_id,body,visibility,created_at,updated_at,idempotency_key,comments_enabled,scheduled_at,is_ad,ad_label,attachment_json,wall_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(user,x.body,x.visibility,this.s.now(),this.s.now(),x.idempotencyKey||null,x.commentsEnabled?1:0,x.scheduledAt||null,x.isAd?1:0,x.isAd?x.adLabel:null,x.attachment?JSON.stringify(x.attachment):null,x.wallUserId||null);const postId=Number(q.lastInsertRowid);this.indexPostMetadata(postId,x.body);this.notifyPostMentions(postId,x.body,user);this.savePoll(postId,x.poll);return {post:this.s.post(postId,user)};}
 @Patch('posts/:id') editPost(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureProfile();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT * FROM posts WHERE id=? AND deleted_at IS NULL').get(+id) as any;if(!user||!post||post.author_id!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};const x=z.object({body:z.string().min(1).max(5000).optional(),visibility:z.enum(['public','friends','private']).optional(),commentsEnabled:z.boolean().optional()}).parse(b);this.s.db.prepare('INSERT INTO post_revisions(post_id,editor_id,body,visibility,created_at) VALUES(?,?,?,?,?)').run(+id,user,post.body,post.visibility,this.s.now());const sets:string[]=[];const values:any[]=[];if(x.body!==undefined){sets.push('body=?');values.push(x.body)}if(x.visibility!==undefined){sets.push('visibility=?');values.push(x.visibility)}if(x.commentsEnabled!==undefined){sets.push('comments_enabled=?');values.push(x.commentsEnabled?1:0)}sets.push('updated_at=?');values.push(this.s.now());this.s.db.prepare(`UPDATE posts SET ${sets.join(',')} WHERE id=?`).run(...values,+id);if(x.body!==undefined){this.indexPostMetadata(+id,x.body);this.notifyPostMentions(+id,x.body,user);}return {post:this.s.post(+id,user)};}
 @Get('posts/:id/metadata') postMetadata(@Param('id') id:string){this.ensureProfile();const post=this.s.db.prepare('SELECT id FROM posts WHERE id=? AND deleted_at IS NULL').get(+id) as any;if(!post)return {hashtags:[],mentions:[],links:[]};return {hashtags:this.s.db.prepare('SELECT tag FROM post_hashtags WHERE post_id=? ORDER BY tag').all(+id),mentions:this.s.db.prepare('SELECT username FROM post_mentions WHERE post_id=? ORDER BY username').all(+id),links:this.s.db.prepare('SELECT url,hostname,title FROM post_links WHERE post_id=?').all(+id)};}
 @Get('posts/:id/media') postMedia(@Param('id') id:string){this.ensurePostMedia();return {items:this.s.db.prepare('SELECT id,kind,url,mime,created_at createdAt FROM post_media WHERE post_id=? ORDER BY id').all(+id)};}
 @Post('posts/:id/media') @UseInterceptors(FilesInterceptor('files',10,{limits:{fileSize:50*1024*1024}})) uploadPostMedia(@Param('id') id:string,@Req() req:any,@UploadedFiles() files:any[]){this.ensurePostMedia();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=? AND deleted_at IS NULL').get(+id) as any;if(!user||!post||post.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};const list=files?.length?files:[];if(!list.length)return {error:'Файл обязателен',code:'NO_FILE'};const items:any[]=[];for(const file of list){const image=/^image\/(jpeg|png|webp|gif)$/.test(file.mimetype);const video=/^video\/(mp4|webm|quicktime)$/.test(file.mimetype);const audio=/^audio\/(mpeg|mp4|wav|ogg|webm)$/.test(file.mimetype);const document=/^(application\/pdf|text\/plain|application\/msword|application\/vnd\.openxmlformats-officedocument\.wordprocessingml\.document)$/.test(file.mimetype);if(!image&&!video&&!audio&&!document)return {error:'Поддерживаются фото, GIF, видео, аудио и документы',code:'INVALID_FILE'};const kind=image?(file.mimetype==='image/gif'?'gif':'photo'):video?'video':audio?'audio':'document';const ext=file.mimetype.split('/')[1].replace('jpeg','jpg').replace('quicktime','mov').replace('vnd.openxmlformats-officedocument.wordprocessingml.document','docx');const filename=`post-${id}-${randomBytes(8).toString('hex')}.${ext}`;mkdirSync(join(process.cwd(),'uploads'),{recursive:true});writeFileSync(join(process.cwd(),'uploads',filename),file.buffer);const url=`/uploads/${filename}`;const q=this.s.db.prepare('INSERT INTO post_media(post_id,user_id,kind,url,mime,created_at) VALUES(?,?,?,?,?,?)').run(+id,user,kind,url,file.mimetype,this.s.now());items.push({id:Number(q.lastInsertRowid),kind,url,mime:file.mimetype});}return {items};}
 @Get('posts/:id/poll') postPoll(@Req() req:any,@Param('id') id:string){this.ensurePollOptions();const user=this.s.auth(req);const poll=this.s.db.prepare('SELECT id,question,multiple,anonymous,allow_change,expires_at expiresAt FROM post_polls WHERE post_id=?').get(+id) as any;if(!poll)return {poll:null};const options=this.s.db.prepare('SELECT o.id,o.label,o.position,(SELECT COUNT(*) FROM poll_votes v WHERE v.option_id=o.id) votes FROM poll_options o WHERE o.poll_id=? ORDER BY o.position').all(poll.id) as any[];const voted=user?this.s.db.prepare('SELECT option_id optionId FROM poll_votes WHERE poll_id=? AND user_id=?').all(poll.id,user):[];return {poll:{...poll,multiple:Boolean(poll.multiple),anonymous:Boolean(poll.anonymous),allowChange:Boolean(poll.allow_change),options,voted}};}
 @Post('posts/:id/poll/vote') votePoll(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensurePollOptions();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const poll=this.s.db.prepare('SELECT * FROM post_polls WHERE post_id=?').get(+id) as any;if(!poll)return {error:'Опрос не найден',code:'NOT_FOUND'};if(poll.expires_at&&Date.parse(poll.expires_at)<=Date.now())return {error:'Опрос завершён',code:'POLL_EXPIRED'};const x=z.object({optionIds:z.array(z.number().int().positive()).min(1).max(10),replace:z.boolean().default(false)}).parse(b);const valid=this.s.db.prepare('SELECT id FROM poll_options WHERE poll_id=? AND id IN ('+x.optionIds.map(()=>'?').join(',')+')').all(poll.id,...x.optionIds) as any[];if(valid.length!==new Set(x.optionIds).size)return {error:'Недопустимый вариант',code:'INVALID_OPTION'};const existing=this.s.db.prepare('SELECT option_id FROM poll_votes WHERE poll_id=? AND user_id=?').all(poll.id,user) as any[];if(existing.length&&!poll.allow_change&&!x.replace)return {error:'Вы уже голосовали',code:'ALREADY_VOTED'};if(existing&&(poll.allow_change||x.replace))this.s.db.prepare('DELETE FROM poll_votes WHERE poll_id=? AND user_id=?').run(poll.id,user);if(!poll.multiple&&x.optionIds.length!==1)return {error:'Выберите один вариант',code:'SINGLE_CHOICE'};const stmt=this.s.db.prepare('INSERT INTO poll_votes(poll_id,option_id,user_id,created_at) VALUES(?,?,?,?)');const tx=this.s.db.transaction(()=>[...new Set(x.optionIds)].forEach(optionId=>stmt.run(poll.id,optionId,user,this.s.now())));tx();return this.postPoll(req,id);}
 @Get('posts/:id/revisions') revisions(@Req() req:any,@Param('id') id:string){this.ensureProfile();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=?').get(+id) as any;if(!user||!post||post.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};return {items:this.s.db.prepare('SELECT id,body,visibility,created_at createdAt FROM post_revisions WHERE post_id=? ORDER BY id DESC').all(+id)};}
 @Post('posts/:id/archive') archivePost(@Req() req:any,@Param('id') id:string){this.ensureProfile();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=?').get(+id) as any;if(!user||!post||post.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};this.s.db.prepare('UPDATE posts SET archived=CASE WHEN archived=1 THEN 0 ELSE 1 END,updated_at=? WHERE id=?').run(this.s.now(),+id);const row=this.s.db.prepare('SELECT archived FROM posts WHERE id=?').get(+id) as any;return {archived:Boolean(row.archived)};}
 @Delete('posts/:id') deletePost(@Req() req:any,@Param('id') id:string){this.ensureEngagement();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=? AND deleted_at IS NULL').get(+id) as any;if(!user||!post||post.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};this.s.db.prepare('UPDATE posts SET deleted_at=?,updated_at=? WHERE id=?').run(this.s.now(),this.s.now(),+id);this.s.db.prepare('DELETE FROM reactions WHERE post_id=?').run(+id);this.s.db.prepare('DELETE FROM comments WHERE post_id=?').run(+id);this.s.db.prepare('DELETE FROM bookmarks WHERE post_id=?').run(+id);this.s.db.prepare('DELETE FROM post_views WHERE post_id=?').run(+id);return {deleted:true};}
 @Get('drafts') drafts(@Req() req:any){this.ensureProfile();const user=this.s.auth(req);return {items:user?this.s.db.prepare('SELECT id,context,body,updated_at updatedAt FROM drafts WHERE user_id=? ORDER BY updated_at DESC').all(user):[]};}
 @Post('drafts') saveDraft(@Req() req:any,@Body() b:any){this.ensureProfile();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({context:z.string().min(1).max(80),body:z.string().max(5000)}).parse(b);this.s.db.prepare('INSERT INTO drafts(user_id,context,body,updated_at) VALUES(?,?,?,?) ON CONFLICT(user_id,context) DO UPDATE SET body=excluded.body,updated_at=excluded.updated_at').run(user,x.context,x.body,this.s.now());return {saved:true};}
 @Delete('drafts/:context') deleteDraft(@Req() req:any,@Param('context') context:string){this.ensureProfile();const user=this.s.auth(req);this.s.db.prepare('DELETE FROM drafts WHERE user_id=? AND context=?').run(user,context);return {deleted:true};}
 private ensureBookmarks(){this.s.db.exec('CREATE TABLE IF NOT EXISTS bookmark_collections(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,name)); CREATE TABLE IF NOT EXISTS bookmark_meta(bookmark_id INTEGER PRIMARY KEY,collection_id INTEGER,tag TEXT);')}
 @Get('bookmarks') bookmarks(@Req() req:any){this.ensureBookmarks();this.ensureProfile();const user=this.s.auth(req);if(!user)return {items:[],collections:[]};const q=String(req.query?.q||'').trim();const collection=Number(req.query?.collection||0);const tag=String(req.query?.tag||'').trim();const sort=String(req.query?.sort||'new')==='old'?'b.id ASC':'b.id DESC';const items=this.s.db.prepare(`SELECT b.id,b.created_at createdAt,p.id postId,p.body,p.visibility,u.username,u.display_name displayName,bm.collection_id collectionId,bm.tag FROM bookmarks b JOIN posts p ON p.id=b.post_id JOIN users u ON u.id=p.author_id LEFT JOIN bookmark_meta bm ON bm.bookmark_id=b.id WHERE b.user_id=? AND p.deleted_at IS NULL AND (?='' OR p.body LIKE ?) AND (?=0 OR bm.collection_id=?) AND (?='' OR bm.tag=?) ORDER BY ${sort}`).all(user,q,`%${q}%`,collection,collection,tag,tag);return {items,collections:this.s.db.prepare('SELECT id,name FROM bookmark_collections WHERE user_id=? ORDER BY name').all(user)};}
 @Post('bookmarks/collections') createBookmarkCollection(@Req() req:any,@Body() b:any){this.ensureBookmarks();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({name:z.string().trim().min(1).max(80)}).parse(b);const q=this.s.db.prepare('INSERT OR IGNORE INTO bookmark_collections(user_id,name,created_at) VALUES(?,?,?)').run(user,x.name,this.s.now());return {id:Number(q.lastInsertRowid),name:x.name};}
 @Delete('bookmarks/collections/:id') deleteBookmarkCollection(@Req() req:any,@Param('id') id:string){this.ensureBookmarks();const user=this.s.auth(req);const q=this.s.db.prepare('DELETE FROM bookmark_collections WHERE id=? AND user_id=?').run(+id,user);this.s.db.prepare('UPDATE bookmark_meta SET collection_id=NULL WHERE collection_id=?').run(+id);return {deleted:q.changes>0};}
 @Post('bookmarks/:postId') addBookmark(@Req() req:any,@Param('postId') postId:string,@Body() b:any){this.ensureBookmarks();this.ensureProfile();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT id FROM posts WHERE id=? AND deleted_at IS NULL').get(+postId);if(!user||!post)return {error:'Недоступная публикация',code:'NOT_FOUND'};this.s.db.prepare('INSERT OR IGNORE INTO bookmarks(user_id,post_id,created_at) VALUES(?,?,?)').run(user,+postId,this.s.now());const bookmark=this.s.db.prepare('SELECT id FROM bookmarks WHERE user_id=? AND post_id=?').get(user,+postId) as any;const collectionId=Number(b?.collectionId||0)||null;const tag=String(b?.tag||'').trim()||null;this.s.db.prepare('INSERT INTO bookmark_meta(bookmark_id,collection_id,tag) VALUES(?,?,?) ON CONFLICT(bookmark_id) DO UPDATE SET collection_id=excluded.collection_id,tag=excluded.tag').run(bookmark.id,collectionId,tag);return {bookmarked:true};}
 @Delete('bookmarks/:postId') removeBookmark(@Req() req:any,@Param('postId') postId:string){this.ensureBookmarks();this.ensureProfile();const user=this.s.auth(req);const bookmark=this.s.db.prepare('SELECT id FROM bookmarks WHERE user_id=? AND post_id=?').get(user,+postId) as any;this.s.db.prepare('DELETE FROM bookmarks WHERE user_id=? AND post_id=?').run(user,+postId);if(bookmark)this.s.db.prepare('DELETE FROM bookmark_meta WHERE bookmark_id=?').run(bookmark.id);return {bookmarked:false};}
 @Post('posts/:id/react') react(@Req() req:any,@Param('id') id:string){const user=this.s.auth(req); if(!user)return {error:'Требуется вход'}; const exists=this.s.db.prepare('SELECT id FROM reactions WHERE post_id=? AND user_id=?').get(+id,user) as any; if(exists)this.s.db.prepare('DELETE FROM reactions WHERE id=?').run(exists.id); else{this.s.db.prepare('INSERT INTO reactions(post_id,user_id) VALUES(?,?)').run(+id,user);this.notifyPostAuthor(+id,user,'reaction',`Ваша публикация получила реакцию`);} return {post:this.s.post(+id,user)};}
 @Get('posts/:id/comments') comments(@Param('id') id:string,@Req() req:any){this.ensureEngagement();const sort=String(req.query?.sort||'new')==='popular'?'reactionCount DESC,c.id DESC':'c.id DESC';return {items:this.s.db.prepare(`SELECT c.*,u.display_name as authorName,(SELECT COUNT(*) FROM comment_reactions cr WHERE cr.comment_id=c.id) reactionCount FROM comments c JOIN users u ON u.id=c.author_id WHERE post_id=? ORDER BY ${sort}`).all(+id)}}
 @Post('posts/:id/comments/subscribe') subscribeDiscussion(@Req() req:any,@Param('id') id:string){this.ensureDiscussion();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};this.s.db.prepare('INSERT OR IGNORE INTO comment_subscriptions(post_id,user_id,created_at) VALUES(?,?,?)').run(+id,user,this.s.now());return {subscribed:true};}
 @Delete('posts/:id/comments/subscribe') unsubscribeDiscussion(@Req() req:any,@Param('id') id:string){this.ensureDiscussion();const user=this.s.auth(req);this.s.db.prepare('DELETE FROM comment_subscriptions WHERE post_id=? AND user_id=?').run(+id,user);return {subscribed:false};}
 @Post('posts/:id/comments') comment(@Req() req:any,@Param('id') id:string,@Body() b:any){const user=this.s.auth(req); if(!user)return {error:'Требуется вход'}; const x=z.object({body:z.string().min(1).max(1000),parentId:z.number().nullable().optional()}).parse(b);if(/(?:купить дешево|casino|viagra)/i.test(x.body))return {error:'Комментарий заблокирован фильтром спама',code:'SPAM_BLOCKED'};const recent=this.s.db.prepare("SELECT COUNT(*) count FROM comments WHERE author_id=? AND created_at>datetime('now','-1 minute')").get(user) as any;if(recent.count>=10)return {error:'Слишком много комментариев',code:'RATE_LIMITED'}; const q=this.s.db.prepare('INSERT INTO comments(post_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)').run(+id,user,x.body,x.parentId??null,this.s.now());this.notifyPostAuthor(+id,user,'comment',`Новый комментарий к вашей публикации`);for(const username of [...x.body.matchAll(/(^|\s)@([a-z0-9_]{3,24})/gi)].map(m=>m[2].toLowerCase())){const target=this.s.db.prepare('SELECT id FROM users WHERE username=? AND id<>?').get(username,user) as any;if(target)this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(target.id,'comment_mention','Вас упомянули в комментарии',this.s.now());}return {id:Number(q.lastInsertRowid),body:x.body,authorName:this.s.user(user)?.displayName};}
 @Get('users') users(@Req() req:any){this.ensureProfile();const viewer=this.s.auth(req);const q=String(req.query?.q||'');const city=String(req.query?.city||'').trim();const minAge=Math.max(0,Number(req.query?.minAge||0));const maxAge=Math.max(0,Number(req.query?.maxAge||0));const rows=this.s.db.prepare("SELECT id,username,display_name as displayName,bio,avatar_url as avatarUrl,privacy_json privacy FROM users WHERE (username LIKE ? OR display_name LIKE ?) AND (?='' OR city LIKE ?) AND (?=0 OR (CAST(strftime('%Y','now') AS INTEGER)-CAST(substr(birth_date,1,4) AS INTEGER))>=?) AND (?=0 OR (CAST(strftime('%Y','now') AS INTEGER)-CAST(substr(birth_date,1,4) AS INTEGER))<=?) AND id!=? AND NOT EXISTS(SELECT 1 FROM user_blocks b WHERE b.blocker_id=? AND b.blocked_id=users.id) LIMIT 30").all(`%${q}%`,`%${q}%`,city,`%${city}%`,minAge,minAge,maxAge,maxAge,viewer||0,viewer||0) as any[];return {items:rows.map(row=>{const privacy=JSON.parse(row.privacy||'{}');delete row.privacy; if(privacy.bio===false)row.bio=null;return row;})}}
 private ensureSearch(){this.s.db.exec('CREATE TABLE IF NOT EXISTS search_history(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,query TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,query))')}
 @Get('search/history') searchHistory(@Req() req:any){this.ensureSearch();const u=this.s.auth(req);return {items:u?this.s.db.prepare('SELECT id,query,created_at createdAt FROM search_history WHERE user_id=? ORDER BY created_at DESC LIMIT 20').all(u):[]};}
 @Post('search/history') saveSearch(@Req() req:any,@Body() b:any){this.ensureSearch();const u=this.s.auth(req);if(!u)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({query:z.string().trim().min(1).max(100)}).parse(b);this.s.db.prepare('INSERT INTO search_history(user_id,query,created_at) VALUES(?,?,?) ON CONFLICT(user_id,query) DO UPDATE SET created_at=excluded.created_at').run(u,x.query,this.s.now());return {ok:true};}
 @Delete('search/history') clearSearchHistory(@Req() req:any){this.ensureSearch();const u=this.s.auth(req);if(u)this.s.db.prepare('DELETE FROM search_history WHERE user_id=?').run(u);return {ok:true};}
 @Get('search') globalSearch(@Req() req:any){this.ensureProfile();const user=this.s.auth(req);const q=String(req.query?.q||'').trim();const type=String(req.query?.type||'all');const cursor=Number(req.query?.cursor||0);const limit=Math.min(Number(req.query?.limit||20),50);if(!q)return {items:[],nextCursor:null};const like='%'+q+'%';const items:any[]=[];if(type==='all'||type==='people')items.push(...this.s.db.prepare('SELECT id,\'people\' type,username,display_name displayName,bio FROM users WHERE deleted_at IS NULL AND id!=? AND (username LIKE ? OR display_name LIKE ?) AND NOT EXISTS(SELECT 1 FROM user_blocks b WHERE b.blocker_id=? AND b.blocked_id=users.id) ORDER BY id DESC LIMIT ?').all(user||0,like,like,user||0,limit));if(type==='all'||type==='posts')items.push(...this.s.db.prepare("SELECT p.id,'post' type,p.body,p.created_at createdAt,u.username,u.display_name displayName FROM posts p JOIN users u ON u.id=p.author_id WHERE p.deleted_at IS NULL AND p.visibility='public' AND p.body LIKE ? AND (?=0 OR p.id<?) ORDER BY p.id DESC LIMIT ?").all(like,user||0,cursor||Number.MAX_SAFE_INTEGER,limit));if(type==='all'||type==='groups'){this.groups();items.push(...this.s.db.prepare("SELECT id,'group' type,name,slug,description FROM groups WHERE name LIKE ? OR slug LIKE ? ORDER BY id DESC LIMIT ?").all(like,like,limit));}return {items:items.slice(0,limit),nextCursor:items.length>=limit?items[items.length-1]?.id:null};}
 @Get('notifications') notifications(@Req() req:any){const u=this.s.auth(req);if(!u)return {items:[]};const kind=String(req.query?.kind||'');const unread=req.query?.unread==='1';const where=['user_id=?'];const params:any[]=[u];if(kind){where.push('kind=?');params.push(kind)}if(unread){where.push('read=0')}return {items:this.s.db.prepare(`SELECT * FROM notifications WHERE ${where.join(' AND ')} ORDER BY id DESC LIMIT 50`).all(...params)};}
 @Post('notifications/:id/read') readNotification(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req);if(!u)return {error:'Требуется вход',code:'UNAUTHORIZED'};const q=this.s.db.prepare('UPDATE notifications SET read=1 WHERE id=? AND user_id=?').run(+id,u);return {read:q.changes>0};}
 @Post('notifications/read-all') readNotifications(@Req() req:any){const u=this.s.auth(req); if(u)this.s.db.prepare('UPDATE notifications SET read=1 WHERE user_id=?').run(u); return {ok:true};}
 @Get('messages') messages(@Req() req:any){this.ensureMessages();const u=this.s.auth(req); return {items:u?this.s.db.prepare('SELECT m.*,u.display_name as senderName FROM messages m JOIN users u ON u.id=m.sender_id WHERE (m.sender_id=? OR m.recipient_id=?) AND m.deleted_at IS NULL AND (m.scheduled_at IS NULL OR m.scheduled_at<=?) ORDER BY m.id').all(u,u,this.s.now()):[]}}
 @Get('messages/folders') messageFolders(@Req() req:any){this.ensureMessages();const user=this.s.auth(req);if(!user)return {items:[]};return {items:this.s.db.prepare('SELECT f.id,f.name,COUNT(p.peer_id) peerCount FROM chat_folders f LEFT JOIN chat_folder_peers p ON p.folder_id=f.id WHERE f.user_id=? GROUP BY f.id ORDER BY f.id').all(user)};}
 @Post('messages/folders') createMessageFolder(@Req() req:any,@Body() b:any){this.ensureMessages();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({name:z.string().trim().min(1).max(60)}).parse(b);const q=this.s.db.prepare('INSERT OR IGNORE INTO chat_folders(user_id,name,created_at) VALUES(?,?,?)').run(user,x.name,this.s.now());return {id:Number(q.lastInsertRowid),name:x.name};}
 @Post('messages/folders/:id/peers') addMessageFolderPeer(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureMessages();const user=this.s.auth(req);const x=z.object({peerId:z.number().int().positive()}).parse(b);const folder=this.s.db.prepare('SELECT id FROM chat_folders WHERE id=? AND user_id=?').get(+id,user);if(!user||!folder||!this.s.user(x.peerId))return {error:'Папка или диалог не найдены',code:'FORBIDDEN'};this.s.db.prepare('INSERT OR IGNORE INTO chat_folder_peers(folder_id,peer_id,created_at) VALUES(?,?,?)').run(+id,x.peerId,this.s.now());return {added:true};}
 @Get('messages/peer/:id/events') messageEvents(@Req() req:any,@Param('id') id:string){this.ensureMessages();const user=this.s.auth(req);if(!user)return {items:[]};const peer=+id;const allowed=this.s.db.prepare('SELECT 1 FROM messages WHERE (sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?) LIMIT 1').get(user,peer,peer,user);return {items:allowed?this.s.db.prepare('SELECT e.id,e.kind,e.text,e.created_at createdAt FROM chat_system_events e WHERE e.peer_id=? ORDER BY e.id DESC LIMIT 50').all(peer):[]};}
 @Get('messages/peer/:id/shared') sharedMessageItems(@Req() req:any,@Param('id') id:string){this.ensureMessages();const user=this.s.auth(req);const peer=+id;if(!user)return {items:[]};const rows=this.s.db.prepare('SELECT id,body,attachments_json attachments,created_at createdAt FROM messages WHERE ((sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?)) AND deleted_at IS NULL ORDER BY id DESC LIMIT 200').all(user,peer,peer,user) as any[];const items:any[]=[];for(const row of rows){let attachments:any[]=[];try{attachments=JSON.parse(row.attachments||'[]')}catch{}if(attachments.length)items.push(...attachments.map(item=>({...item,messageId:row.id,createdAt:row.createdAt})));for(const url of row.body.split(/\s+/).filter((part:string)=>/^https?:\/\//i.test(part)))items.push({type:'link',url,messageId:row.id,createdAt:row.createdAt});}return {items};}
 @Post('messages/peer/:id/block') blockMessagePeer(@Req() req:any,@Param('id') id:string){this.ensureProfile();const user=this.s.auth(req);const peer=+id;if(!user||user===peer)return {error:'Недопустимое действие',code:'FORBIDDEN'};this.s.db.prepare('INSERT OR IGNORE INTO user_blocks(blocker_id,blocked_id,created_at) VALUES(?,?,?)').run(user,peer,this.s.now());return {blocked:true};}
 @Post('messages/peer/:id/report') reportMessagePeer(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureProfile();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({reason:z.string().trim().min(1).max(500)}).parse(b);this.s.db.prepare('INSERT INTO reports(reporter_id,target_type,target_id,reason,created_at) VALUES(?,?,?,?,?)').run(user,'user',+id,x.reason,this.s.now());return {reported:true};}
 @Get('messages/peer/:id/preferences') messagePreferences(@Req() req:any,@Param('id') id:string){this.ensureMessages();const user=this.s.auth(req);if(!user)return {muted:false,archived:false,pinned:false,favorite:false};return this.s.db.prepare('SELECT muted,archived,pinned,favorite FROM chat_preferences WHERE user_id=? AND peer_id=?').get(user,+id)||{muted:false,archived:false,pinned:false,favorite:false};}
 @Post('messages/peer/:id/preferences') updateMessagePreferences(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureMessages();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({muted:z.boolean().default(false),archived:z.boolean().default(false),pinned:z.boolean().default(false),favorite:z.boolean().default(false)}).parse(b);this.s.db.prepare('INSERT INTO chat_preferences(user_id,peer_id,muted,archived,pinned,favorite,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(user_id,peer_id) DO UPDATE SET muted=excluded.muted,archived=excluded.archived,pinned=excluded.pinned,favorite=excluded.favorite,updated_at=excluded.updated_at').run(user,+id,x.muted?1:0,x.archived?1:0,x.pinned?1:0,x.favorite?1:0,this.s.now());const changed=x.archived?'Чат перемещён в архив':x.pinned?'Чат закреплён':x.muted?'Уведомления чата отключены':'Настройки чата изменены';this.s.db.prepare('INSERT INTO chat_system_events(peer_id,actor_id,kind,text,created_at) VALUES(?,?,?,?,?)').run(+id,user,'preference',changed,this.s.now());return x;}
 @Get('messages/chats') messageChats(@Req() req:any){this.ensureMessages();const user=this.s.auth(req);if(!user)return {items:[]};const q=String(req.query?.q||'').trim();const peers=this.s.db.prepare("SELECT CASE WHEN m.sender_id=? THEN m.recipient_id ELSE m.sender_id END peerId,MAX(m.id) lastId FROM messages m WHERE (m.sender_id=? OR m.recipient_id=?) AND m.deleted_at IS NULL GROUP BY peerId ORDER BY lastId DESC").all(user,user,user) as any[];const items=peers.map(row=>{const peer=this.s.db.prepare('SELECT id,username,display_name displayName,avatar_url avatarUrl FROM users WHERE id=?').get(row.peerId) as any;if(!peer||q&&!(String(peer.username).toLowerCase().includes(q.toLowerCase())||String(peer.displayName).toLowerCase().includes(q.toLowerCase())))return null;const last=this.s.db.prepare('SELECT id,body,created_at createdAt,read_at readAt FROM messages WHERE id=?').get(row.lastId) as any;const unread=this.s.db.prepare('SELECT COUNT(*) count FROM messages WHERE sender_id=? AND recipient_id=? AND read_at IS NULL AND deleted_at IS NULL').get(row.peerId,user) as any;const pref=this.s.db.prepare('SELECT favorite,archived,pinned FROM chat_preferences WHERE user_id=? AND peer_id=?').get(user,row.peerId) as any;return {...peer,lastMessage:last,unread:Number(unread?.count||0),favorite:Boolean(pref?.favorite),archived:Boolean(pref?.archived),pinned:Boolean(pref?.pinned)};}).filter(Boolean);return {items};}
 @Get('messages/peer/:id') peerMessages(@Req() req:any,@Param('id') id:string){this.ensureMessages();const user=this.s.auth(req);if(!user)return {items:[]};const peer=+id;const before=Number(req.query?.before||0);const limit=Math.min(Number(req.query?.limit||50),100);const rows=this.s.db.prepare(`SELECT m.*,u.display_name senderName FROM messages m JOIN users u ON u.id=m.sender_id WHERE ((m.sender_id=? AND m.recipient_id=?) OR (m.sender_id=? AND m.recipient_id=?)) AND m.deleted_at IS NULL AND (m.scheduled_at IS NULL OR m.scheduled_at<=?) ${before?'AND m.id<?':''} ORDER BY m.id DESC LIMIT ?`).all(...(before?[user,peer,peer,user,this.s.now(),before,limit]:[user,peer,peer,user,this.s.now(),limit])) as any[];this.s.db.prepare('UPDATE messages SET read_at=? WHERE sender_id=? AND recipient_id=? AND read_at IS NULL AND (scheduled_at IS NULL OR scheduled_at<=?)').run(this.s.now(),peer,user,this.s.now());return {items:rows.reverse(),nextBefore:rows.length===limit?rows[0]?.id:null};}
 @Post('messages') send(@Req() req:any,@Body() b:any){this.ensureMessages();const u=this.s.auth(req);if(!u)return {error:'Требуется вход'};const x=z.object({recipientId:z.number(),body:z.string().max(5000).default(''),replyTo:z.number().int().positive().nullable().optional(),attachments:z.array(z.any()).max(10).default([]),silent:z.boolean().default(false),scheduledAt:z.string().datetime().nullable().optional(),idempotencyKey:z.string().trim().min(8).max(120).nullable().optional()}).refine(v=>v.body.trim().length>0||v.attachments.length>0,{message:'Сообщение или вложение обязательно'}).parse(b);if(!this.s.user(x.recipientId))return {error:'Получатель не найден',code:'NOT_FOUND'};if(x.idempotencyKey){const existing=this.s.db.prepare('SELECT * FROM messages WHERE sender_id=? AND client_key=?').get(u,x.idempotencyKey) as any;if(existing)return {...existing,duplicate:true};}const createdAt=this.s.now();const q=this.s.db.prepare('INSERT INTO messages(sender_id,recipient_id,body,created_at,attachments_json,reply_to,silent,scheduled_at,client_key) VALUES(?,?,?,?,?,?,?,?,?)').run(u,x.recipientId,x.body,createdAt,JSON.stringify(x.attachments),x.replyTo||null,x.silent?1:0,x.scheduledAt||null,x.idempotencyKey||null);const message={id:Number(q.lastInsertRowid),body:x.body,senderId:u,recipientId:x.recipientId,attachments:x.attachments,replyTo:x.replyTo||null,silent:x.silent,scheduledAt:x.scheduledAt||null,createdAt};if(!x.scheduledAt||x.scheduledAt<=createdAt)this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(x.recipientId,'message','Новое сообщение',createdAt);return message;}
 @Post('messages/:id/read') readMessage(@Req() req:any,@Param('id') id:string){this.ensureMessages();const u=this.s.auth(req);const q=this.s.db.prepare('UPDATE messages SET read_at=? WHERE id=? AND recipient_id=?').run(this.s.now(),+id,u);return {read:q.changes>0};}
 @Patch('messages/:id') editMessage(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureMessages();const u=this.s.auth(req);const x=z.object({body:z.string().min(1).max(5000)}).parse(b);const q=this.s.db.prepare('UPDATE messages SET body=?,edited_at=? WHERE id=? AND sender_id=? AND deleted_at IS NULL').run(x.body,this.s.now(),+id,u);return {edited:q.changes>0};}
 @Delete('messages/:id') deleteMessage(@Req() req:any,@Param('id') id:string){this.ensureMessages();const u=this.s.auth(req);const q=this.s.db.prepare('UPDATE messages SET deleted_at=? WHERE id=? AND (sender_id=? OR recipient_id=?)').run(this.s.now(),+id,u,u);return {deleted:q.changes>0};}
 @Post('messages/:id/react') reactMessage(@Req() req:any,@Param('id') id:string){this.ensureMessages();const u=this.s.auth(req);if(!u)return {error:'Требуется вход',code:'UNAUTHORIZED'};const allowed=this.s.db.prepare('SELECT 1 FROM messages WHERE id=? AND (sender_id=? OR recipient_id=?)').get(+id,u,u);if(!allowed)return {error:'Недоступное сообщение',code:'FORBIDDEN'};const old=this.s.db.prepare('SELECT 1 FROM message_reactions WHERE message_id=? AND user_id=?').get(+id,u);if(old)this.s.db.prepare('DELETE FROM message_reactions WHERE message_id=? AND user_id=?').run(+id,u);else this.s.db.prepare('INSERT INTO message_reactions(message_id,user_id) VALUES(?,?)').run(+id,u);return {reacted:!old};}
 @Post('messages/:id/forward') forwardMessage(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureMessages();const u=this.s.auth(req);const x=z.object({recipientId:z.number().int().positive()}).parse(b);const source=this.s.db.prepare('SELECT m.body,m.sender_id senderId,u.display_name senderName FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.id=? AND (m.sender_id=? OR m.recipient_id=?) AND m.deleted_at IS NULL').get(+id,u,u) as any;if(!u||!source||!this.s.user(x.recipientId))return {error:'Недоступное сообщение',code:'FORBIDDEN'};const body=`Переслано от ${source.senderName}: ${source.body}`;const q=this.s.db.prepare('INSERT INTO messages(sender_id,recipient_id,body,created_at,attachments_json,reply_to,silent) VALUES(?,?,?,?,?,?,?)').run(u,x.recipientId,body,this.s.now(),'[]',null,0);return {id:Number(q.lastInsertRowid),body,forwardedFrom:source.senderId};}
 @Post('messages/:id/pin') pinMessage(@Req() req:any,@Param('id') id:string){this.ensureMessages();const u=this.s.auth(req);const allowed=this.s.db.prepare('SELECT 1 FROM messages WHERE id=? AND (sender_id=? OR recipient_id=?)').get(+id,u,u);if(!u||!allowed)return {error:'Недоступное сообщение',code:'FORBIDDEN'};const q=this.s.db.prepare('UPDATE messages SET pinned=CASE WHEN pinned=1 THEN 0 ELSE 1 END WHERE id=?').run(+id);const row=this.s.db.prepare('SELECT pinned FROM messages WHERE id=?').get(+id) as any;return {pinned:Boolean(row?.pinned),updated:q.changes>0};}
 @Post('follow/:id') follow(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req),t=+id; if(!u||u===t)return {error:'Недопустимое действие'}; const e=this.s.db.prepare('SELECT id FROM follows WHERE follower_id=? AND following_id=?').get(u,t) as any; if(e)this.s.db.prepare('DELETE FROM follows WHERE id=?').run(e.id);else this.s.db.prepare('INSERT INTO follows(follower_id,following_id) VALUES(?,?)').run(u,t); return {following:!e};}
 @Get('friends') friends(@Req() req:any){const u=this.s.auth(req); if(!u)return {items:[]}; return {items:this.s.db.prepare(`SELECT f.id,f.status,f.requester_id requesterId,f.addressee_id addresseeId,CASE WHEN f.addressee_id=? AND f.status='pending' THEN 1 ELSE 0 END incoming,x.id userId,x.username,x.display_name displayName FROM friendships f JOIN users x ON x.id=CASE WHEN f.requester_id=? THEN f.addressee_id ELSE f.requester_id END WHERE f.requester_id=? OR f.addressee_id=? ORDER BY f.id DESC`).all(u,u,u,u)};}
 @Post('friends/:id/request') friendRequest(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req),t=+id;if(!u||u===t)return {error:'Недопустимое действие'};const existing=this.s.db.prepare('SELECT * FROM friendships WHERE (requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?)').get(u,t,t,u) as any;if(existing)return {status:existing.status};this.s.db.prepare('INSERT INTO friendships(requester_id,addressee_id) VALUES(?,?)').run(u,t);this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(t,'friend_request',`${this.s.user(u)?.displayName} отправил(а) вам заявку в друзья`,this.s.now());return {status:'pending'};}
 @Post('friends/:id/accept') acceptFriend(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req);const row=this.s.db.prepare("SELECT requester_id requesterId FROM friendships WHERE id=? AND addressee_id=? AND status='pending'").get(+id,u) as any;const q=this.s.db.prepare("UPDATE friendships SET status='accepted' WHERE id=? AND addressee_id=?").run(+id,u);if(q.changes&&row)this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(row.requesterId,'friend_accepted',`${this.s.user(u)?.displayName||'Пользователь'} принял(а) вашу заявку в друзья`,this.s.now());return {accepted:q.changes>0};}
 @Post('friends/:id/reject') rejectFriend(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req);const row=this.s.db.prepare("SELECT requester_id requesterId FROM friendships WHERE id=? AND addressee_id=? AND status='pending'").get(+id,u) as any;const q=this.s.db.prepare("DELETE FROM friendships WHERE id=? AND addressee_id=? AND status='pending'").run(+id,u);if(q.changes&&row)this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(row.requesterId,'friend_rejected','Ваша заявка в друзья была отклонена',this.s.now());return {rejected:q.changes>0};}
 @Delete('friends/:id/request') cancelFriendRequest(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req);const q=this.s.db.prepare("DELETE FROM friendships WHERE id=? AND requester_id=? AND status='pending'").run(+id,u);return {cancelled:q.changes>0};}
 @Delete('friends/:id') removeFriend(@Req() req:any,@Param('id') id:string){const u=this.s.auth(req);const q=this.s.db.prepare("DELETE FROM friendships WHERE id=? AND status='accepted' AND (requester_id=? OR addressee_id=?)").run(+id,u,u);return {removed:q.changes>0};}
 @Get('groups') groups(){this.s.db.exec('CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER NOT NULL,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,description TEXT NOT NULL DEFAULT \'\',created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS group_members(id INTEGER PRIMARY KEY AUTOINCREMENT,group_id INTEGER NOT NULL,user_id INTEGER NOT NULL,role TEXT NOT NULL DEFAULT \'member\',UNIQUE(group_id,user_id)); CREATE TABLE IF NOT EXISTS group_posts(id INTEGER PRIMARY KEY AUTOINCREMENT,group_id INTEGER NOT NULL,author_id INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,deleted_at TEXT)');return {items:this.s.db.prepare('SELECT id,name,slug,description,created_at createdAt FROM groups ORDER BY id DESC').all()};}
 @Post('groups') createGroup(@Req() req:any,@Body() b:any){this.groups();const u=this.s.auth(req);if(!u)return {error:'Требуется вход'};const x=z.object({name:z.string().min(2).max(100),slug:z.string().min(2).max(40).regex(/^[a-z0-9-]+$/),description:z.string().max(1000).default('')}).parse(b);try{const q=this.s.db.prepare('INSERT INTO groups(owner_id,name,slug,description,created_at) VALUES(?,?,?,?,?)').run(u,x.name,x.slug,x.description,this.s.now());this.s.db.prepare('INSERT INTO group_members(group_id,user_id,role) VALUES(?,?,?)').run(Number(q.lastInsertRowid),u,'owner');return {group:{id:Number(q.lastInsertRowid),...x}};}catch{return {error:'Такой slug уже занят',code:'CONFLICT'}}}
 @Get('groups/:slug') group(@Param('slug') slug:string,@Req() req:any){this.groups();const g=this.s.db.prepare('SELECT id,name,slug,description,created_at createdAt FROM groups WHERE slug=?').get(slug) as any;if(!g)return {group:null};const user=this.s.auth(req);const membership=user?this.s.db.prepare('SELECT role FROM group_members WHERE group_id=? AND user_id=?').get(g.id,user) as any:null;return {group:{...g,membership:membership?.role||null,members:this.s.db.prepare('SELECT u.id,u.username,u.display_name displayName,gm.role FROM group_members gm JOIN users u ON u.id=gm.user_id WHERE gm.group_id=?').all(g.id)}}}
 @Post('groups/:slug/join') joinGroup(@Req() req:any,@Param('slug') slug:string){this.groups();const user=this.s.auth(req);const g=this.s.db.prepare('SELECT id FROM groups WHERE slug=?').get(slug) as any;if(!user||!g)return {error:'Группа не найдена',code:'NOT_FOUND'};this.s.db.prepare("INSERT OR IGNORE INTO group_members(group_id,user_id,role) VALUES(?,?, 'member')").run(g.id,user);return {joined:true};}
 @Delete('groups/:slug/leave') leaveGroup(@Req() req:any,@Param('slug') slug:string){this.groups();const user=this.s.auth(req);const g=this.s.db.prepare('SELECT id,owner_id ownerId FROM groups WHERE slug=?').get(slug) as any;if(!user||!g)return {error:'Группа не найдена',code:'NOT_FOUND'};if(g.ownerId===user)return {error:'Владелец не может выйти из своей группы',code:'OWNER_REQUIRED'};const q=this.s.db.prepare('DELETE FROM group_members WHERE group_id=? AND user_id=?').run(g.id,user);return {left:q.changes>0};}
 @Patch('groups/:slug/members/:userId') updateGroupRole(@Req() req:any,@Param('slug') slug:string,@Param('userId') userId:string,@Body() b:any){this.groups();const actor=this.s.auth(req);const g=this.s.db.prepare('SELECT id,owner_id ownerId FROM groups WHERE slug=?').get(slug) as any;if(!actor||!g||g.ownerId!==actor)return {error:'Требуются права владельца',code:'FORBIDDEN'};const role=z.enum(['member','moderator','admin']).parse(b.role);const q=this.s.db.prepare("UPDATE group_members SET role=? WHERE group_id=? AND user_id=?").run(role,g.id,+userId);return {updated:q.changes>0,role};}
 @Get('groups/:slug/posts') groupPosts(@Param('slug') slug:string){this.groups();const g=this.s.db.prepare('SELECT id FROM groups WHERE slug=?').get(slug) as any;if(!g)return {items:[]};return {items:this.s.db.prepare('SELECT gp.id,gp.body,gp.created_at createdAt,u.id authorId,u.username,u.display_name displayName FROM group_posts gp JOIN users u ON u.id=gp.author_id WHERE gp.group_id=? AND gp.deleted_at IS NULL ORDER BY gp.id DESC LIMIT 50').all(g.id)};}
 @Post('groups/:slug/posts') createGroupPost(@Req() req:any,@Param('slug') slug:string,@Body() b:any){this.groups();const user=this.s.auth(req);const g=this.s.db.prepare('SELECT id FROM groups WHERE slug=?').get(slug) as any;if(!user||!g)return {error:'Группа не найдена',code:'NOT_FOUND'};const member=this.s.db.prepare("SELECT role FROM group_members WHERE group_id=? AND user_id=?").get(g.id,user) as any;if(!member||!['owner','admin','moderator'].includes(member.role))return {error:'Недостаточно прав',code:'FORBIDDEN'};const x=z.object({body:z.string().min(1).max(5000)}).parse(b);const q=this.s.db.prepare('INSERT INTO group_posts(group_id,author_id,body,created_at) VALUES(?,?,?,?)').run(g.id,user,x.body,this.s.now());return {id:Number(q.lastInsertRowid),...x,authorId:user};}
 @Get('profile/:username') profile(@Param('username') username:string,@Req() req:any){this.ensureProfile();const viewer=this.s.auth(req);const u=this.s.db.prepare("SELECT id,username,display_name as displayName,first_name firstName,last_name lastName,nickname,bio,avatar_url as avatarUrl,cover_url as coverUrl,status,emoji_status emojiStatus,verified,city,country,birth_date birthDate,education,career,contacts,family_status familyStatus,website,interests,signature,privacy_json privacy,last_seen lastSeen,created_at createdAt FROM users WHERE username=? AND deleted_at IS NULL").get(username) as any;if(!u)return {user:null};const isSelf=viewer===u.id;const isFriend=Boolean(isSelf||this.s.db.prepare("SELECT 1 FROM friendships WHERE status='accepted' AND ((requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?))").get(viewer,u.id,u.id,viewer));const privacy=JSON.parse(u.privacy||'{}');const exceptionRows=this.s.db.prepare('SELECT field,allowed FROM privacy_exceptions WHERE owner_id=? AND viewer_id=?').all(u.id,viewer||0) as any[];const exceptions=new Set(exceptionRows.filter(x=>x.allowed).map(x=>x.field));const friends=this.s.db.prepare("SELECT COUNT(*) count FROM friendships WHERE status='accepted' AND (requester_id=? OR addressee_id=?)").get(u.id,u.id) as any;const followers=this.s.db.prepare('SELECT COUNT(*) count FROM follows WHERE following_id=?').get(u.id) as any;const posts=this.s.db.prepare('SELECT COUNT(*) count FROM posts WHERE author_id=? AND deleted_at IS NULL').get(u.id) as any;const media=this.s.db.prepare("SELECT SUM(kind='photo') photos,SUM(kind='clip') clips,SUM(kind='video') videos FROM profile_media WHERE user_id=?").get(u.id) as any;const mediaItems=this.s.db.prepare("SELECT id,kind,url,created_at createdAt FROM profile_media WHERE user_id=? AND kind IN ('photo','clip','video') ORDER BY id DESC LIMIT 30").all(u.id);const commonQuery="SELECT x.id,x.username,x.display_name displayName,x.avatar_url avatarUrl FROM users x WHERE x.id NOT IN (?,?) AND EXISTS(SELECT 1 FROM friendships a WHERE a.status='accepted' AND ((a.requester_id=? AND a.addressee_id=x.id) OR (a.addressee_id=? AND a.requester_id=x.id))) AND EXISTS(SELECT 1 FROM friendships b WHERE b.status='accepted' AND ((b.requester_id=? AND b.addressee_id=x.id) OR (b.addressee_id=? AND b.requester_id=x.id))) ORDER BY x.display_name LIMIT 30";const commonFriends=viewer?this.s.db.prepare(commonQuery).all(viewer,u.id,viewer,viewer,u.id,u.id):[];const following=Boolean(viewer&&this.s.db.prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?').get(viewer,u.id));if(!isSelf){for(const key of ['bio','status','emojiStatus','city','country','birthDate','education','career','contacts','familyStatus','website','interests'])if(privacy[key]===false&&!exceptions.has(key))u[key]=null;}const closed=Boolean(!isSelf&&!isFriend&&privacy.profileClosed===true&&!exceptions.has('profileClosed'));if(closed){for(const key of ['firstName','lastName','nickname','bio','status','emojiStatus','city','country','birthDate','education','career','contacts','familyStatus','website','interests'])u[key]=null;}const canSeeFriends=isSelf||isFriend||privacy.friends!==false;const friendItems=canSeeFriends?this.s.db.prepare("SELECT x.id,x.username,x.display_name displayName,x.avatar_url avatarUrl FROM friendships f JOIN users x ON x.id=CASE WHEN f.requester_id=? THEN f.addressee_id ELSE f.requester_id END WHERE f.status='accepted' AND (f.requester_id=? OR f.addressee_id=?) ORDER BY x.display_name LIMIT 30").all(u.id,u.id,u.id):[];delete u.privacy;return {user:{...u,online:Boolean(u.lastSeen&&Date.now()-Date.parse(u.lastSeen)<5*60*1000),isSelf,isFriend,following,private:closed,counts:{friends:friends.count,followers:followers.count,posts:posts.count,photos:Number(media?.photos||0),clips:Number(media?.clips||0),videos:Number(media?.videos||0),commonFriends:commonFriends.length},mediaItems, friends:friendItems,commonFriends,links:isSelf||isFriend?this.s.db.prepare('SELECT id,title,url,created_at createdAt FROM profile_links WHERE user_id=? ORDER BY id DESC').all(u.id):[],privacy:isSelf?privacy:undefined}};}
 @Get('profile/:username/privacy-exceptions') privacyExceptions(@Param('username') username:string,@Req() req:any){this.ensureProfile();const owner=this.s.auth(req);const target=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!owner||!target||owner!==target.id)return {items:[]};return {items:this.s.db.prepare('SELECT viewer_id viewerId,field,allowed FROM privacy_exceptions WHERE owner_id=? ORDER BY viewer_id,field').all(owner)};}
 @Post('profile/:username/privacy-exceptions') setPrivacyException(@Param('username') username:string,@Req() req:any,@Body() b:any){this.ensureProfile();const owner=this.s.auth(req);const target=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!owner||!target||owner!==target.id)return {error:'Недостаточно прав',code:'FORBIDDEN'};const x=z.object({viewerId:z.number().int().positive(),field:z.string().trim().min(1).max(40),allowed:z.boolean().default(true)}).parse(b);this.s.db.prepare('INSERT INTO privacy_exceptions(owner_id,viewer_id,field,allowed,created_at) VALUES(?,?,?,?,?) ON CONFLICT(owner_id,viewer_id,field) DO UPDATE SET allowed=excluded.allowed,created_at=excluded.created_at').run(owner,x.viewerId,x.field,x.allowed?1:0,this.s.now());return {saved:true};}
 @Get('profile/:username/links') profileLinks(@Param('username') username:string,@Req() req:any){this.ensureProfile();const viewer=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!u)return {items:[]};const allowed=viewer===u.id||Boolean(this.s.db.prepare("SELECT 1 FROM friendships WHERE status='accepted' AND ((requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?))").get(viewer,u.id,u.id,viewer));return {items:allowed?this.s.db.prepare('SELECT id,title,url,created_at createdAt FROM profile_links WHERE user_id=? ORDER BY id DESC').all(u.id):[]};}
 @Post('profile/:username/links') addProfileLink(@Param('username') username:string,@Req() req:any,@Body() b:any){this.ensureProfile();const viewer=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!viewer||!u||viewer!==u.id)return {error:'Недостаточно прав',code:'FORBIDDEN'};const x=z.object({title:z.string().trim().min(1).max(80),url:z.string().url().max(500)}).parse(b);const q=this.s.db.prepare('INSERT INTO profile_links(user_id,title,url,created_at) VALUES(?,?,?,?)').run(viewer,x.title,x.url,this.s.now());return {id:Number(q.lastInsertRowid),...x};}
 @Delete('profile/:username/links/:id') deleteProfileLink(@Param('username') username:string,@Param('id') id:string,@Req() req:any){this.ensureProfile();const viewer=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!viewer||!u||viewer!==u.id)return {error:'Недостаточно прав',code:'FORBIDDEN'};const q=this.s.db.prepare('DELETE FROM profile_links WHERE id=? AND user_id=?').run(+id,u.id);return {deleted:q.changes>0};}
 @Patch('profile/:username') updateProfile(@Param('username') username:string,@Req() req:any,@Body() b:any){this.ensureProfile();const id=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!id||!u||id!==u.id)return {error:'Недостаточно прав',code:'FORBIDDEN'};const x=z.object({displayName:z.string().trim().min(2).max(80).optional(),firstName:z.string().trim().max(80).nullable().optional(),lastName:z.string().trim().max(80).nullable().optional(),nickname:z.string().trim().max(80).nullable().optional(),bio:z.string().max(2000).nullable().optional(),avatarUrl:z.string().url().nullable().optional(),coverUrl:z.string().url().nullable().optional(),status:z.string().max(140).nullable().optional(),emojiStatus:z.string().max(16).nullable().optional(),city:z.string().max(120).nullable().optional(),country:z.string().max(120).nullable().optional(),birthDate:z.string().max(20).nullable().optional(),education:z.string().max(200).nullable().optional(),career:z.string().max(200).nullable().optional(),contacts:z.string().max(1000).nullable().optional(),familyStatus:z.string().max(80).nullable().optional(),website:z.string().url().nullable().optional(),interests:z.string().max(500).nullable().optional(),signature:z.string().max(160).nullable().optional(),privacy:z.record(z.boolean()).optional()}).parse(b);const sets:string[]=[];const values:any[]=[];const map:any={displayName:'display_name',firstName:'first_name',lastName:'last_name',nickname:'nickname',bio:'bio',avatarUrl:'avatar_url',coverUrl:'cover_url',status:'status',emojiStatus:'emoji_status',city:'city',country:'country',birthDate:'birth_date',education:'education',career:'career',contacts:'contacts',familyStatus:'family_status',website:'website',interests:'interests',signature:'signature'};for(const [key,column] of Object.entries(map)){if(key in x){sets.push(`${column}=?`);values.push((x as any)[key])}}if(x.privacy){sets.push('privacy_json=?');values.push(JSON.stringify(x.privacy))}if(sets.length){sets.push('last_seen=?');values.push(this.s.now());this.s.db.prepare(`UPDATE users SET ${sets.join(',')} WHERE id=?`).run(...values,id)}return {user:this.s.db.prepare("SELECT id,username,display_name as displayName,first_name firstName,last_name lastName,nickname,bio,avatar_url as avatarUrl,cover_url as coverUrl,status,emoji_status emojiStatus,city,country,birth_date birthDate,education,career,contacts,family_status familyStatus,website,interests,signature,privacy_json privacy FROM users WHERE id=?").get(id)};}
 @Post('profile/:username/media') @UseInterceptors(FileInterceptor('file')) uploadProfileMedia(@Param('username') username:string,@Req() req:any,@UploadedFile() file:any){this.ensureProfile();const id=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!id||!u||id!==u.id)return {error:'Недостаточно прав',code:'FORBIDDEN'};if(!file)return {error:'Файл обязателен',code:'NO_FILE'};const kind=String(req.query?.kind||'avatar');if(!['avatar','cover','photo','clip','video'].includes(kind))return {error:'Неверный тип медиа',code:'INVALID_KIND'};const image=/^image\/(jpeg|png|webp|gif)$/.test(file.mimetype);const movie=/^video\/(mp4|webm|quicktime)$/.test(file.mimetype);const valid=(kind==='avatar'||kind==='cover'||kind==='photo')?image:movie;const max=kind==='avatar'||kind==='cover'?5*1024*1024:100*1024*1024;if(!valid||file.size>max)return {error:'Неподдерживаемый формат или размер файла',code:'INVALID_FILE'};const ext=file.mimetype.split('/')[1].replace('jpeg','jpg').replace('quicktime','mov');const filename=`${id}-${kind}-${randomBytes(8).toString('hex')}.${ext}`;mkdirSync(join(process.cwd(),'uploads'),{recursive:true});writeFileSync(join(process.cwd(),'uploads',filename),file.buffer);const url=`/uploads/${filename}`;this.s.db.prepare('INSERT INTO profile_media(user_id,kind,url,created_at) VALUES(?,?,?,?)').run(id,kind,url,this.s.now());if(kind==='avatar'||kind==='cover')this.s.db.prepare(`UPDATE users SET ${kind==='avatar'?'avatar_url':'cover_url'}=? WHERE id=?`).run(url,id);return {url,kind};}
 @Get('profile/:username/media-history') mediaHistory(@Param('username') username:string,@Req() req:any){this.ensureProfile();const id=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!id||!u||id!==u.id)return {error:'Недостаточно прав',code:'FORBIDDEN'};return {items:this.s.db.prepare('SELECT id,kind,url,created_at createdAt FROM profile_media WHERE user_id=? ORDER BY id DESC').all(id)};}
 @Get('profile/:username/posts') profilePosts(@Param('username') username:string,@Req() req:any){this.ensureProfile();const viewer=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=?').get(username) as any;if(!u)return {items:[]};const blocked=this.s.db.prepare('SELECT 1 FROM user_blocks WHERE blocker_id=? AND blocked_id=?').get(viewer,u.id);if(blocked)return {items:[]};const rows=this.s.db.prepare("SELECT id FROM posts WHERE author_id=? AND deleted_at IS NULL AND (archived=0 OR author_id=?) AND (visibility='public' OR author_id=? OR (visibility='friends' AND EXISTS(SELECT 1 FROM friendships f WHERE f.status='accepted' AND ((f.requester_id=? AND f.addressee_id=?) OR (f.addressee_id=? AND f.requester_id=?))))) ORDER BY pinned DESC,id DESC LIMIT 50").all(u.id,viewer,viewer,viewer,u.id,viewer,u.id) as any[];return {items:rows.map(x=>this.s.post(x.id,viewer)).filter(Boolean)};}
 @Post('posts/:id/pin') pinPost(@Req() req:any,@Param('id') id:string){this.ensureProfile();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=?').get(+id) as any;if(!user||!post||post.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};this.s.db.prepare('UPDATE posts SET pinned=CASE WHEN pinned=1 THEN 0 ELSE 1 END WHERE id=?').run(+id);return {pinned:Boolean((this.s.db.prepare('SELECT pinned FROM posts WHERE id=?').get(+id) as any).pinned)};}
 @Post('users/:id/block') blockUser(@Req() req:any,@Param('id') id:string){this.ensureProfile();const user=this.s.auth(req);const target=+id;if(!user||user===target)return {error:'Недопустимое действие'};this.s.db.prepare('INSERT OR IGNORE INTO user_blocks(blocker_id,blocked_id,created_at) VALUES(?,?,?)').run(user,target,this.s.now());return {blocked:true};}
 @Delete('users/:id/block') unblockUser(@Req() req:any,@Param('id') id:string){this.ensureProfile();const user=this.s.auth(req);this.s.db.prepare('DELETE FROM user_blocks WHERE blocker_id=? AND blocked_id=?').run(user,+id);return {blocked:false};}
 @Post('reports') report(@Req() req:any,@Body() b:any){this.ensureProfile();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({targetType:z.enum(['user','post','comment']),targetId:z.number().int().positive(),reason:z.string().min(3).max(500)}).parse(b);const q=this.s.db.prepare('INSERT INTO reports(reporter_id,target_type,target_id,reason,created_at) VALUES(?,?,?,?,?)').run(user,x.targetType,x.targetId, x.reason,this.s.now());return {reportId:Number(q.lastInsertRowid),status:'open'};}
 @Get('profile/:username/recommendations') profileRecommendations(@Param('username') username:string,@Req() req:any){this.ensureProfile();const viewer=this.s.auth(req);const u=this.s.db.prepare('SELECT id FROM users WHERE username=? AND deleted_at IS NULL').get(username) as any;if(!u)return {items:[]};return {items:this.s.db.prepare("SELECT x.id,x.username,x.display_name displayName,x.avatar_url avatarUrl,COUNT(f2.id) mutualFriends FROM users x LEFT JOIN friendships f2 ON f2.status='accepted' AND (f2.requester_id=x.id OR f2.addressee_id=x.id) WHERE x.id NOT IN (?,?) AND x.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM friendships f WHERE f.status='accepted' AND ((f.requester_id=? AND f.addressee_id=x.id) OR (f.addressee_id=? AND f.requester_id=x.id))) GROUP BY x.id ORDER BY mutualFriends DESC,x.created_at DESC LIMIT 12").all(u.id,viewer||0,viewer||0,viewer||0)};}
 @Post('profile/:username/verification') requestVerification(@Param('username') username:string,@Req() req:any,@Body() b:any){this.ensureProfileExtras();const user=this.s.auth(req);const target=this.s.db.prepare('SELECT id FROM users WHERE username=? AND deleted_at IS NULL').get(username) as any;if(!user||!target||target.id!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};const note=z.object({note:z.string().max(1000).default('')}).parse(b||{}).note;try{const q=this.s.db.prepare("INSERT INTO profile_verification_requests(user_id,note,created_at) VALUES(?,?,?)").run(user,note,this.s.now());return {requestId:Number(q.lastInsertRowid),status:'pending'};}catch{return {error:'Заявка уже существует',code:'CONFLICT'};}}
 @Get('gifts') gifts(){this.ensureProfileExtras();return {items:this.s.db.prepare('SELECT id,name,emoji FROM gifts WHERE active=1 ORDER BY id').all()};}
 @Get('profile/:username/gifts') profileGifts(@Param('username') username:string){this.ensureProfileExtras();const u=this.s.db.prepare('SELECT id FROM users WHERE username=? AND deleted_at IS NULL').get(username) as any;if(!u)return {items:[]};return {items:this.s.db.prepare('SELECT ug.id,ug.message,ug.created_at createdAt,g.name,g.emoji,u.username senderUsername,u.display_name senderName FROM user_gifts ug JOIN gifts g ON g.id=ug.gift_id JOIN users u ON u.id=ug.sender_id WHERE ug.recipient_id=? ORDER BY ug.id DESC LIMIT 50').all(u.id)};}
 @Post('profile/:username/gifts') sendGift(@Param('username') username:string,@Req() req:any,@Body() b:any){this.ensureProfileExtras();const sender=this.s.auth(req);const recipient=this.s.db.prepare('SELECT id FROM users WHERE username=? AND deleted_at IS NULL').get(username) as any;if(!sender||!recipient||sender===recipient.id)return {error:'Недопустимое действие',code:'FORBIDDEN'};const x=z.object({giftId:z.number().int().positive(),message:z.string().max(300).default('')}).parse(b);const gift=this.s.db.prepare('SELECT id FROM gifts WHERE id=? AND active=1').get(x.giftId);if(!gift)return {error:'Подарок не найден',code:'NOT_FOUND'};const q=this.s.db.prepare('INSERT INTO user_gifts(gift_id,sender_id,recipient_id,message,created_at) VALUES(?,?,?,?,?)').run(x.giftId,sender,recipient.id,x.message,this.s.now());this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(recipient.id,'gift','Вам отправили подарок',this.s.now());return {id:Number(q.lastInsertRowid),sent:true};}
 @Post('posts/:id/location') setPostLocation(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensurePostLocation();const user=this.s.auth(req);const post=this.s.db.prepare('SELECT author_id authorId FROM posts WHERE id=? AND deleted_at IS NULL').get(+id) as any;if(!user||!post||post.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};const x=z.object({latitude:z.number().gte(-90).lte(90),longitude:z.number().gte(-180).lte(180),label:z.string().max(160).default('')}).parse(b);this.s.db.prepare('INSERT INTO post_locations(post_id,latitude,longitude,label,created_at) VALUES(?,?,?,?,?) ON CONFLICT(post_id) DO UPDATE SET latitude=excluded.latitude,longitude=excluded.longitude,label=excluded.label').run(+id,x.latitude,x.longitude,x.label,this.s.now());return {postId:+id,...x};}
 @Get('posts/:id/location') getPostLocation(@Param('id') id:string){this.ensurePostLocation();return {location:this.s.db.prepare('SELECT latitude,longitude,label,created_at createdAt FROM post_locations WHERE post_id=?').get(+id)||null};}
 private ensureEngagement(){this.ensureProfile();try{this.s.db.exec("ALTER TABLE posts ADD COLUMN repost_of INTEGER")}catch{}this.s.db.exec('CREATE TABLE IF NOT EXISTS post_views(post_id INTEGER NOT NULL,user_id INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(post_id,user_id)); CREATE TABLE IF NOT EXISTS reposts(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,user_id INTEGER NOT NULL,comment TEXT,created_at TEXT NOT NULL,UNIQUE(post_id,user_id)); CREATE TABLE IF NOT EXISTS comment_reactions(comment_id INTEGER NOT NULL,user_id INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT \'like\',UNIQUE(comment_id,user_id));')}
 @Get('posts/:id/reactions') reactions(@Param('id') id:string){this.ensureEngagement();return {items:this.s.db.prepare("SELECT r.kind,u.id userId,u.username,u.display_name displayName FROM reactions r JOIN users u ON u.id=r.user_id WHERE r.post_id=? ORDER BY r.id DESC LIMIT 100").all(+id)};}
 @Post('posts/:id/view') viewPost(@Req() req:any,@Param('id') id:string){this.ensureEngagement();const user=this.s.auth(req);if(!user)return {unique:false};const q=this.s.db.prepare('INSERT OR IGNORE INTO post_views(post_id,user_id,created_at) VALUES(?,?,?)').run(+id,user,this.s.now());return {unique:q.changes>0};}
 @Get('posts/:id/views') postViews(@Param('id') id:string){this.ensureEngagement();const row=this.s.db.prepare('SELECT COUNT(*) count FROM post_views WHERE post_id=?').get(+id) as any;return {count:Number(row?.count||0)};}
 @Post('posts/:id/repost') repost(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureEngagement();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const source=this.s.db.prepare('SELECT body,visibility FROM posts WHERE id=? AND deleted_at IS NULL').get(+id) as any;if(!source)return {error:'Публикация не найдена',code:'NOT_FOUND'};const x=z.object({comment:z.string().max(1000).default(''),visibility:z.enum(['public','friends','private']).default('public')}).parse(b||{});const q=this.s.db.prepare('INSERT INTO posts(author_id,body,visibility,created_at,updated_at,repost_of) VALUES(?,?,?,?,?,?)').run(user,x.comment||source.body,x.visibility,this.s.now(),this.s.now(),+id);const postId=Number(q.lastInsertRowid);this.s.db.prepare('INSERT OR IGNORE INTO reposts(post_id,user_id,comment,created_at) VALUES(?,?,?,?)').run(+id,user,x.comment,this.s.now());return {post:this.s.post(postId,user),sourcePostId:+id};}
 @Get('posts/:id/reposts') reposts(@Param('id') id:string){this.ensureEngagement();return {items:this.s.db.prepare('SELECT r.id,r.comment,r.created_at createdAt,u.id userId,u.username,u.display_name displayName FROM reposts r JOIN users u ON u.id=r.user_id WHERE r.post_id=? ORDER BY r.id DESC LIMIT 100').all(+id)};}
 @Patch('comments/:id') editComment(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureEngagement();const user=this.s.auth(req);const x=z.object({body:z.string().min(1).max(1000)}).parse(b);const q=this.s.db.prepare('UPDATE comments SET body=? WHERE id=? AND author_id=?').run(x.body,+id,user);return {updated:q.changes>0};}
 @Delete('comments/:id') deleteComment(@Req() req:any,@Param('id') id:string){this.ensureDiscussion();const user=this.s.auth(req);const q=this.s.db.prepare("DELETE FROM comments WHERE id=? AND (author_id=? OR post_id IN (SELECT id FROM posts WHERE author_id=?))").run(+id,user,user);if(q.changes)this.s.db.prepare('INSERT INTO moderation_audit(actor_id,action,target_type,target_id,created_at) VALUES(?,?,?,?,?)').run(user,'delete','comment',+id,this.s.now());return {deleted:q.changes>0};}
 @Post('comments/:id/pin') pinComment(@Req() req:any,@Param('id') id:string){this.ensureDiscussion();const user=this.s.auth(req);const comment=this.s.db.prepare('SELECT c.post_id postId,p.author_id authorId FROM comments c JOIN posts p ON p.id=c.post_id WHERE c.id=?').get(+id) as any;if(!user||!comment||comment.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};this.s.db.prepare('UPDATE comments SET pinned=CASE WHEN pinned=1 THEN 0 ELSE 1 END WHERE id=?').run(+id);const row=this.s.db.prepare('SELECT pinned FROM comments WHERE id=?').get(+id) as any;this.s.db.prepare('INSERT INTO moderation_audit(actor_id,action,target_type,target_id,created_at) VALUES(?,?,?,?,?)').run(user,'pin','comment',+id,this.s.now());return {pinned:Boolean(row.pinned)};}
 @Post('comments/:id/media') @UseInterceptors(FileInterceptor('file')) uploadCommentMedia(@Req() req:any,@Param('id') id:string,@UploadedFile() file:any){this.ensureDiscussion();const user=this.s.auth(req);const comment=this.s.db.prepare('SELECT author_id authorId FROM comments WHERE id=?').get(+id) as any;if(!user||!comment||comment.authorId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};if(!file)return {error:'Файл обязателен',code:'NO_FILE'};const image=/^image\/(jpeg|png|webp|gif)$/.test(file.mimetype);const video=/^video\/(mp4|webm|quicktime)$/.test(file.mimetype);if((!image&&!video)||file.size>20*1024*1024)return {error:'Разрешены фото/GIF/видео до 20 МБ',code:'INVALID_FILE'};const kind=image?(file.mimetype==='image/gif'?'gif':'photo'):'video';const ext=file.mimetype.split('/')[1].replace('jpeg','jpg').replace('quicktime','mov');const filename=`comment-${id}-${randomBytes(8).toString('hex')}.${ext}`;mkdirSync(join(process.cwd(),'uploads'),{recursive:true});writeFileSync(join(process.cwd(),'uploads',filename),file.buffer);const url=`/uploads/${filename}`;const q=this.s.db.prepare('INSERT INTO comment_media(comment_id,user_id,kind,url,mime,created_at) VALUES(?,?,?,?,?,?)').run(+id,user,kind,url,file.mimetype,this.s.now());return {id:Number(q.lastInsertRowid),kind,url};}
 @Get('comments/:id/media') commentMedia(@Param('id') id:string){this.ensureDiscussion();return {items:this.s.db.prepare('SELECT id,kind,url,mime,created_at createdAt FROM comment_media WHERE comment_id=? ORDER BY id').all(+id)};}
 @Post('comments/:id/react') reactComment(@Req() req:any,@Param('id') id:string){this.ensureEngagement();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const e=this.s.db.prepare('SELECT 1 FROM comment_reactions WHERE comment_id=? AND user_id=?').get(+id,user);if(e)this.s.db.prepare('DELETE FROM comment_reactions WHERE comment_id=? AND user_id=?').run(+id,user);else this.s.db.prepare('INSERT INTO comment_reactions(comment_id,user_id) VALUES(?,?)').run(+id,user);return {reacted:!e};}
 private ensureChatGroups(){this.s.db.exec("CREATE TABLE IF NOT EXISTS chat_groups(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',avatar_url TEXT,type TEXT NOT NULL DEFAULT 'group',created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS chat_group_members(group_id INTEGER NOT NULL,user_id INTEGER NOT NULL,role TEXT NOT NULL DEFAULT 'member',created_at TEXT NOT NULL,UNIQUE(group_id,user_id)); CREATE TABLE IF NOT EXISTS chat_group_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,group_id INTEGER NOT NULL,user_id INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,deleted_at TEXT); CREATE TABLE IF NOT EXISTS chat_group_invites(token TEXT PRIMARY KEY,group_id INTEGER NOT NULL,created_by INTEGER NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS call_history(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER NOT NULL,peer_id INTEGER,group_id INTEGER,kind TEXT NOT NULL DEFAULT 'audio',status TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT); CREATE INDEX IF NOT EXISTS chat_group_messages_idx ON chat_group_messages(group_id,id);");try{this.s.db.exec("ALTER TABLE chat_groups ADD COLUMN type TEXT NOT NULL DEFAULT 'group'")}catch{}}
 private chatGroupRole(groupId:number,userId:number){return this.s.db.prepare('SELECT role FROM chat_group_members WHERE group_id=? AND user_id=?').get(groupId,userId) as any}
 @Get('messages/calls') callHistory(@Req() req:any){this.ensureChatGroups();const user=this.s.auth(req);if(!user)return {items:[]};return {items:this.s.db.prepare('SELECT id,peer_id peerId,group_id groupId,kind,status,started_at startedAt,ended_at endedAt FROM call_history WHERE owner_id=? ORDER BY id DESC LIMIT 100').all(user)};}
 @Post('messages/calls') startCall(@Req() req:any,@Body() b:any){this.ensureChatGroups();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({peerId:z.number().int().positive().nullable().optional(),groupId:z.number().int().positive().nullable().optional(),kind:z.enum(['audio','video']).default('audio')}).refine(v=>v.peerId||v.groupId,{message:'Укажите получателя или группу'}).parse(b);const q=this.s.db.prepare('INSERT INTO call_history(owner_id,peer_id,group_id,kind,status,started_at) VALUES(?,?,?,?,?,?)').run(user,x.peerId||null,x.groupId||null,x.kind,'started',this.s.now());return {id:Number(q.lastInsertRowid),status:'started',kind:x.kind,startedAt:this.s.now()};}
 @Post('messages/calls/:id/end') endCall(@Req() req:any,@Param('id') id:string){this.ensureChatGroups();const user=this.s.auth(req);const q=this.s.db.prepare("UPDATE call_history SET status='ended',ended_at=? WHERE id=? AND owner_id=? AND status='started'").run(this.s.now(),+id,user);return {ended:q.changes>0};}
 @Get('friends/lists') friendLists(@Req() req:any){this.ensureFriends();const user=this.s.auth(req);if(!user)return {items:[]};return {items:this.s.db.prepare('SELECT l.id,l.name,l.close_friends closeFriends,COUNT(m.user_id) memberCount FROM friend_lists l LEFT JOIN friend_list_members m ON m.list_id=l.id WHERE l.user_id=? GROUP BY l.id ORDER BY l.id').all(user)};}
 @Post('friends/lists') createFriendList(@Req() req:any,@Body() b:any){this.ensureFriends();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({name:z.string().trim().min(1).max(60),closeFriends:z.boolean().default(false)}).parse(b);const q=this.s.db.prepare('INSERT OR IGNORE INTO friend_lists(user_id,name,close_friends,created_at) VALUES(?,?,?,?)').run(user,x.name,x.closeFriends?1:0,this.s.now());return {id:Number(q.lastInsertRowid),name:x.name,closeFriends:x.closeFriends};}
 @Post('friends/lists/:id/members') addFriendListMember(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureFriends();const user=this.s.auth(req);const x=z.object({userId:z.number().int().positive()}).parse(b);const list=this.s.db.prepare('SELECT id FROM friend_lists WHERE id=? AND user_id=?').get(+id,user);const friend=this.s.db.prepare("SELECT 1 FROM friendships WHERE status='accepted' AND ((requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?))").get(user,x.userId,x.userId,user);if(!user||!list||!friend)return {error:'Участник не является вашим другом',code:'FORBIDDEN'};this.s.db.prepare('INSERT OR IGNORE INTO friend_list_members(list_id,user_id,created_at) VALUES(?,?,?)').run(+id,x.userId,this.s.now());return {added:true};}
 @Delete('friends/lists/:id/members/:userId') removeFriendListMember(@Req() req:any,@Param('id') id:string,@Param('userId') userId:string){this.ensureFriends();const user=this.s.auth(req);const q=this.s.db.prepare('DELETE FROM friend_list_members WHERE list_id IN (SELECT id FROM friend_lists WHERE id=? AND user_id=?) AND user_id=?').run(+id,user,+userId);return {removed:q.changes>0};}
 @Get('friends/birthdays') friendBirthdays(@Req() req:any){this.ensureFriends();this.ensureProfile();const user=this.s.auth(req);if(!user)return {items:[]};const items=this.s.db.prepare("SELECT u.id,u.username,u.display_name displayName,u.birth_date birthDate FROM users u JOIN friendships f ON f.status='accepted' AND ((f.requester_id=? AND f.addressee_id=u.id) OR (f.addressee_id=? AND f.requester_id=u.id)) WHERE u.birth_date IS NOT NULL AND substr(u.birth_date,6,5)>=strftime('%m-%d','now') ORDER BY substr(u.birth_date,6,5) LIMIT 30").all(user,user) as any[];const year=new Date().getFullYear();for(const item of items){const text='Скоро день рождения у '+item.displayName;const exists=this.s.db.prepare("SELECT 1 FROM birthday_reminders WHERE user_id=? AND friend_id=? AND birth_year=?").get(user,item.id,year);if(!exists){this.s.db.prepare('INSERT INTO birthday_reminders(user_id,friend_id,birth_year,created_at) VALUES(?,?,?,?)').run(user,item.id,year,this.s.now());this.s.db.prepare('INSERT INTO notifications(user_id,kind,text,created_at) VALUES(?,?,?,?)').run(user,'birthday',text,this.s.now());}}return {items};}
 @Post('friends/import') importContacts(@Req() req:any,@Body() b:any){this.ensureFriends();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({consent:z.literal(true),contacts:z.array(z.string().trim().min(1).max(160)).max(500)}).parse(b);const found:any[]=[];for(const contact of x.contacts){const normalized=contact.toLowerCase();const match=this.s.db.prepare('SELECT id,username,display_name displayName FROM users WHERE lower(email)=? OR lower(username)=?').get(normalized,normalized) as any;this.s.db.prepare('INSERT OR IGNORE INTO contact_imports(user_id,contact,matched_user_id,created_at) VALUES(?,?,?,?)').run(user,contact,match?.id||null,this.s.now());if(match&&match.id!==user)found.push(match);}return {items:found,consentRecorded:true};}
 @Get('friends/online') onlineFriends(@Req() req:any){this.ensureProfile();const user=this.s.auth(req);if(!user)return {items:[]};return {items:this.s.db.prepare("SELECT u.id,u.username,u.display_name displayName,u.avatar_url avatarUrl FROM friendships f JOIN users u ON u.id=CASE WHEN f.requester_id=? THEN f.addressee_id ELSE f.requester_id END WHERE f.status='accepted' AND (f.requester_id=? OR f.addressee_id=?) AND u.last_seen IS NOT NULL AND datetime(u.last_seen)>datetime('now','-5 minutes')").all(user,user,user)};}
 @Get('chat-groups') chatGroups(@Req() req:any){this.ensureChatGroups();const user=this.s.auth(req);if(!user)return {items:[]};return {items:this.s.db.prepare('SELECT g.id,g.name,g.description,g.avatar_url avatarUrl,g.type,m.role,(SELECT COUNT(*) FROM chat_group_members x WHERE x.group_id=g.id) memberCount FROM chat_groups g JOIN chat_group_members m ON m.group_id=g.id WHERE m.user_id=? ORDER BY g.id DESC').all(user)};}
 @Post('chat-groups') createChatGroup(@Req() req:any,@Body() b:any){this.ensureChatGroups();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const x=z.object({name:z.string().trim().min(1).max(120),description:z.string().max(500).default(''),avatarUrl:z.string().url().nullable().optional(),type:z.enum(['group','channel','community','bot']).default('group')}).parse(b);const q=this.s.db.prepare('INSERT INTO chat_groups(owner_id,name,description,avatar_url,type,created_at) VALUES(?,?,?,?,?,?)').run(user,x.name,x.description,x.avatarUrl||null,x.type,this.s.now());const id=Number(q.lastInsertRowid);this.s.db.prepare('INSERT INTO chat_group_members(group_id,user_id,role,created_at) VALUES(?,?,?,?)').run(id,user,'owner',this.s.now());return {id,name:x.name,description:x.description,type:x.type,role:'owner'};}
 @Get('chat-groups/:id') getChatGroup(@Req() req:any,@Param('id') id:string){this.ensureChatGroups();const user=this.s.auth(req);const g=this.s.db.prepare('SELECT id,name,description,avatar_url avatarUrl,owner_id ownerId FROM chat_groups WHERE id=?').get(+id) as any;const role=user&&this.chatGroupRole(+id,user);if(!g||!role)return {error:'Чат не найден',code:'NOT_FOUND'};return {...g,role:role.role,members:this.s.db.prepare('SELECT u.id,u.username,u.display_name displayName,m.role FROM chat_group_members m JOIN users u ON u.id=m.user_id WHERE m.group_id=? ORDER BY m.role,m.id').all(+id)};}
 @Post('chat-groups/:id/members') addChatGroupMember(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureChatGroups();const user=this.s.auth(req);const role=user&&this.chatGroupRole(+id,user);if(!role||!['owner','admin'].includes(role.role))return {error:'Недостаточно прав',code:'FORBIDDEN'};const target=z.number().int().positive().parse(b.userId);if(!this.s.user(target))return {error:'Пользователь не найден',code:'NOT_FOUND'};this.s.db.prepare('INSERT OR IGNORE INTO chat_group_members(group_id,user_id,role,created_at) VALUES(?,?,?,?)').run(+id,target,'member',this.s.now());return {added:true};}
 @Delete('chat-groups/:id/members/:userId') removeChatGroupMember(@Req() req:any,@Param('id') id:string,@Param('userId') userId:string){this.ensureChatGroups();const user=this.s.auth(req);const role=user&&this.chatGroupRole(+id,user);if(!role||!['owner','admin'].includes(role.role))return {error:'Недостаточно прав',code:'FORBIDDEN'};const q=this.s.db.prepare('DELETE FROM chat_group_members WHERE group_id=? AND user_id=? AND user_id<>?').run(+id,+userId,user);return {removed:q.changes>0};}
 @Patch('chat-groups/:id/members/:userId') setChatGroupRole(@Req() req:any,@Param('id') id:string,@Param('userId') userId:string,@Body() b:any){this.ensureChatGroups();const user=this.s.auth(req);const role=user&&this.chatGroupRole(+id,user);if(!role||role.role!=='owner')return {error:'Недостаточно прав',code:'FORBIDDEN'};const next=z.enum(['member','moderator','admin']).parse(b.role);const q=this.s.db.prepare('UPDATE chat_group_members SET role=? WHERE group_id=? AND user_id=?').run(next,+id,+userId);return {updated:q.changes>0,role:next};}
 @Get('chat-groups/:id/messages') chatGroupMessages(@Req() req:any,@Param('id') id:string){this.ensureChatGroups();const user=this.s.auth(req);if(!user||!this.chatGroupRole(+id,user))return {items:[]};const before=Number(req.query?.before||0);const limit=Math.min(Number(req.query?.limit||50),100);const rows=this.s.db.prepare(`SELECT m.id,m.body,m.created_at createdAt,m.user_id userId,u.display_name displayName FROM chat_group_messages m JOIN users u ON u.id=m.user_id WHERE m.group_id=? AND m.deleted_at IS NULL ${before?'AND m.id<?':''} ORDER BY m.id DESC LIMIT ?`).all(...(before?[+id,before,limit]:[+id,limit])) as any[];return {items:rows.reverse(),nextBefore:rows.length===limit?rows[0]?.id:null};}
 @Post('chat-groups/:id/messages') sendChatGroupMessage(@Req() req:any,@Param('id') id:string,@Body() b:any){this.ensureChatGroups();const user=this.s.auth(req);const role=user&&this.chatGroupRole(+id,user);if(!user||!role)return {error:'Нет доступа',code:'FORBIDDEN'};this.s.db.exec("CREATE TABLE IF NOT EXISTS chat_group_settings(group_id INTEGER PRIMARY KEY,max_members INTEGER NOT NULL DEFAULT 100000,join_policy TEXT NOT NULL DEFAULT 'open',permissions_json TEXT NOT NULL DEFAULT '{}',discussion_group_id INTEGER,deleted_at TEXT)");const setting=this.s.db.prepare('SELECT permissions_json permissions,deleted_at deletedAt FROM chat_group_settings WHERE group_id=?').get(+id) as any;const permissions=JSON.parse(setting?.permissions||'{}');if(!['owner','admin','moderator'].includes(role.role)&&permissions.sendMessages===false)return {error:'В этом чате запрещено отправлять сообщения',code:'FORBIDDEN'};const x=z.object({body:z.string().trim().min(1).max(5000)}).parse(b);if(/(^|\s)@all\b/i.test(x.body)&&!['owner','admin'].includes(role.role))return {error:'@all доступен только владельцу и администраторам',code:'FORBIDDEN'};const q=this.s.db.prepare('INSERT INTO chat_group_messages(group_id,user_id,body,created_at) VALUES(?,?,?,?)').run(+id,user,x.body,this.s.now());const group=this.s.db.prepare('SELECT type,owner_id ownerId FROM chat_groups WHERE id=?').get(+id) as any;if(group?.type==='bot')this.s.db.prepare('INSERT INTO chat_group_messages(group_id,user_id,body,created_at) VALUES(?,?,?,?)').run(+id,group.ownerId,'Бот получил сообщение: '+x.body,this.s.now());return {id:Number(q.lastInsertRowid),body:x.body,userId:user,createdAt:this.s.now()};}
 @Post('chat-groups/:id/invites') createChatGroupInvite(@Req() req:any,@Param('id') id:string){this.ensureChatGroups();const user=this.s.auth(req);const role=user&&this.chatGroupRole(+id,user);if(!role||!['owner','admin'].includes(role.role))return {error:'Недостаточно прав',code:'FORBIDDEN'};const expires=new Date(Date.now()+7*86400000).toISOString();const token=randomBytes(18).toString('hex');this.s.db.prepare('INSERT INTO chat_group_invites(token,group_id,created_by,expires_at,created_at) VALUES(?,?,?,?,?)').run(token,+id,user,expires,this.s.now());return {token,expiresAt:expires};}
 @Post('chat-groups/invite/:token') acceptChatGroupInvite(@Req() req:any,@Param('token') token:string){this.ensureChatGroups();const user=this.s.auth(req);if(!user)return {error:'Требуется вход',code:'UNAUTHORIZED'};const invite=this.s.db.prepare('SELECT group_id groupId,expires_at expiresAt FROM chat_group_invites WHERE token=?').get(token) as any;if(!invite||invite.expiresAt&&invite.expiresAt<this.s.now())return {error:'Ссылка недействительна',code:'NOT_FOUND'};this.s.db.exec("CREATE TABLE IF NOT EXISTS chat_group_settings(group_id INTEGER PRIMARY KEY,max_members INTEGER NOT NULL DEFAULT 100000,join_policy TEXT NOT NULL DEFAULT 'open',permissions_json TEXT NOT NULL DEFAULT '{}',discussion_group_id INTEGER,deleted_at TEXT)");const settings=this.s.db.prepare('SELECT max_members maxMembers,join_policy joinPolicy,deleted_at deletedAt FROM chat_group_settings WHERE group_id=?').get(invite.groupId) as any;if(settings?.deletedAt)return {error:'Чат удалён',code:'GONE'};const members=this.s.db.prepare('SELECT COUNT(*) count FROM chat_group_members WHERE group_id=?').get(invite.groupId) as any;if(Number(members?.count||0)>=(settings?.maxMembers||100000))return {error:'Достигнут лимит участников',code:'LIMIT_REACHED'};if(settings?.joinPolicy==='request')return {pending:true,groupId:invite.groupId};this.s.db.prepare('INSERT OR IGNORE INTO chat_group_members(group_id,user_id,role,created_at) VALUES(?,?,?,?)').run(invite.groupId,user,'member',this.s.now());return {joined:true,groupId:invite.groupId};}
 @Delete('chat-groups/:id/members/self') leaveChatGroup(@Req() req:any,@Param('id') id:string){this.ensureChatGroups();const user=this.s.auth(req);const role=user&&this.chatGroupRole(+id,user);if(!role||role.role==='owner')return {error:'Владелец не может выйти без передачи прав',code:'FORBIDDEN'};const q=this.s.db.prepare('DELETE FROM chat_group_members WHERE group_id=? AND user_id=?').run(+id,user);return {left:q.changes>0};}
 @Delete('chat-groups/:id') deleteChatGroup(@Req() req:any,@Param('id') id:string){this.ensureChatGroups();const user=this.s.auth(req);const g=this.s.db.prepare('SELECT owner_id ownerId FROM chat_groups WHERE id=?').get(+id) as any;if(!g||g.ownerId!==user)return {error:'Недостаточно прав',code:'FORBIDDEN'};this.s.db.prepare('DELETE FROM chat_group_messages WHERE group_id=?').run(+id);this.s.db.prepare('DELETE FROM chat_group_members WHERE group_id=?').run(+id);const q=this.s.db.prepare('DELETE FROM chat_groups WHERE id=?').run(+id);return {deleted:q.changes>0};}
}
